quests[79254] = { id = 79254, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Immerstrom" }
quests[79256] = { id = 79256, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Anflug von Furcht", description = "Mein Vater glaubt, dass er seinen alten Hammer Furchtbrecher spürte, als er und Dagran sich um die Skardyn im Süden kümmerten.\n\nEr sagte, der Hammer sei ihm aus den Fingern gerutscht, als Dalaran abstürzte, und es hat sehr an ihm gezehrt. Dieser Hammer gehört dem Bronzebartklan, und zwar seit Generationen. Aber er ist in letzter Zeit auch nicht er selbst.\n\nIch bin bereit, mich selbst umzusehen, damit er sich keine Sorgen machen muss, dass er ihn verpasst hat. Trefft mich im Camp Murroch, dann machen wir uns auf die Suche.", sourceObjective = "Trefft Moira Thaurissan vor Camp Murroch.", completion = "Also wirklich...\n\nIch hätte nicht erwartet, Furchtbrecher hier zu sehen.\n\nEr ist wirklich hier, aber nicht gerade leicht zu erreichen.", sourceObjectiveStatus = "unverified-source-field" }
quests[79257] = { id = 79257, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grottengefahr" }
quests[79258] = { id = 79258, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mineralwassermisere", description = "Als dieser magische Hammer in die Tiefen fiel, wusste ich, dass er eine großartige Waffe gegen die Skardynbedrohung sein könnte. Unser Freund sagte mir, dass er in Bezug auf seinen Träger etwas \"eigen\" ist.\n\nGlücklicherweise bin ich ein Held!\n\nUnd als Held weiß ich, dass wir uns mit einer guten Mischung aus Pollen und Wasser bedecken müssen, wenn wir in seine Nähe kommen wollen. Auf diese Weise wird die Bestie, die darüber steht, glauben, dass wir genau so sind wie sie.\n\nDas Mineralwasser muss genau die richtige Temperatur haben, um sich mit dem Peitschenpilzstaub zu vermischen, damit es funktioniert.", sourceObjective = "Findet Mineralwasser mit der richtigen Temperatur in den Quellen der Lebenden Grotte.", completion = "Das war wirklich unerfreulich. Aber wir haben das Wasser, das Berrund wollte.\n\nWir sollten uns beeilen. Ich will nicht, dass der Hammer meines Vaters da im Matsch versinkt. Das gefällt mir nicht im Geringsten.", sourceObjectiveStatus = "unverified-source-field" }
quests[79259] = { id = 79259, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Macht ein fröhliches Gesicht", description = "Berrund hier sagt, dass diese riesige Bestie, die über Furchtbrecher steht, sehr eigen darin ist, welche Arten von Kreaturen sie in ihrer Nähe duldet.\n\nWenn wir uns tarnen können, sagt er, kommen wir nahe genug heran, um uns den Hammer zu schnappen. Aber um uns zu tarnen, müssen wir uns in Staub und Pollen aus der Grotte hüllen.\n\nDiese Peitschenpilze sehen nach einem guten Anfang aus.\n\nDas kommt mir alles sehr verdächtig vor, aber wir sollten vorerst mitspielen, bis ich Furchtbrecher bergen und zurück zu meinem Vater bringen kann.", sourceObjective = "Sammelt Peitschenpilzstaub von Peitschenpilzen in der Lebenden Grotte.", progress = "Habt Ihr den Staub gesammelt? Das ist der einzige Weg, wie wir an diesen Hammer kommen, besonders, solange diese Kreatur hier herumwandert.", completion = "<Berrund der Glänzende scheint kein Körnchen Pollen an sich zu haben.>\n\nIhr habt Euch ja ganz schön mit dem Peitschenpilzstaub eingedeckt.\n\nIch bin etwas überrascht, dass Ihr nicht mit Juck- und Niesreiz zu kämpfen habt, wie Euer Freund hier.", sourceObjectiveStatus = "unverified-source-field" }
quests[79260] = { id = 79260, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Epizentrum", description = "Zwischen uns und dem Hammer steht diese Kreatur. Sie hat einen gewaltigen Eindruck hinterlassen, als sie hier in den Schallenden Tiefen gelandet ist, nicht wahr? Schaut Euch nur die Größe von diesem Krater an!\n\nWenn Ihr so in Pollen und Wasser gehüllt seid, solltet Ihr in der Lage sein, Euch der Bestie zu nähern und, zumindest theoretisch, dabei nicht verletzt zu werden. Ihr werdet kein Bisschen auffallen!\n\nUnd keine Sorge, wenn die Bestie doch aggressiv wird, ich bin direkt hinter Euch.\n\nWir holen den Hammer hier sicher raus!", sourceObjective = "Nähert Euch dem Peridotkoloss.", completion = "Oh, dieser bernsteinleckende, schleimrückgratige Misthaufen von einem Irdenen! Ich habe Troggs mit mehr Ehre im Leib gesehen!\n\nEr hat Furchtbrecher gestohlen! Er hat den Hammer meiner Familie gestohlen und uns hier zurückgelassen, damit diese Kreatur uns tötet!\n\nDas ist unverzeihlich. Ich werde eine derartige Respektlosigkeit Euch gegenüber... und auch mir gegenüber... nicht zulassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[79261] = { id = 79261, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kochend vor Wut", description = "Dieser undankbare Kieskopf! Er hat Furchtbrecher gestohlen und ist Richtung Norden geflohen!\n\nIch will diesen Hammer nicht für mich selbst. Aber er gehört dem Bronzebartklan. Er sollte von jemandem geführt werden, der seine Macht respektiert!\n\nWir müssen ihn aufspüren, bevor er sich selbst oder jemand anderen mit diesem Hammer verletzt!", sourceObjective = "Verfolgt Berrund und Furchtbrecher durch die Schallenden Tiefen.", completion = "Diese Irdenen hatten keine gute Zeit.\n\nBerrund ist bereits kopfüber da rein gerannt, aber wenn er das Übel hier wirklich austreiben möchte, dann steckt er definitiv in der Klemme.\n\n<Moira deutet auf den steinernen Bruch in der Nähe.>\n\nSchaut, er kann den alten Furchtbrecher kaum noch halten! Was, wenn er ihn fallen lässt und stirbt? Wir müssen ihn finden.", sourceObjectiveStatus = "unverified-source-field" }
quests[79262] = { id = 79262, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frühjahrsputz", description = "Wie es scheint, hat die Zerstörung um den Kernweg mehr losgebrochen als nur ein paar Steine. Es hat alle möglichen düsteren Wesen aufgeweckt.\n\nWenn das hier mal eine gut laufende Mine war, dann ist das Vergangenheit.\n\nWir müssen den Irdenen helfen, sie wieder unter Kontrolle zu bekommen, und das bedeutet, diese Bestien auszudünnen.", sourceObjective = "Tötet aufgeschreckte Kreaturen in der Grollenden Einöde.", progress = "Ich will Furchtbrecher zurück, aber wir müssen zuerst einige dieser aufgeschreckten Kreaturen erlegen.", completion = "Das ist schon etwas besser. Wenigstens laufen hier jetzt nicht mehr so viele dieser Kreaturen Amok.\n\nJetzt haben wir andere Probleme.\n\nNämlich Skardyn.", sourceObjectiveStatus = "unverified-source-field" }
quests[79263] = { id = 79263, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erdspalten", description = "Berrund hat Furchtbrecher an sich genommen. Scheinbar dachte er, dass er diese Leute retten kann... der Held sein kann.\n\nAber man kann nicht etwas Falsches aus den richtigen Gründen tun. Das weiß ich nur zu gut. Wenn ein Fels schon von Anfang an hohl ist, kann er nie wieder solide werden, wie sehr man es auch versucht.\n\nJetzt muss er vermutlich selbst gerettet werden. Durchsuchen wir diesen verfluchten Ort und finden wir ihn.", sourceObjective = "Findet Berrund den Schimmernden in der Grollenden Einöde.", completion = "<Die Haut von Berrund dem Glänzenden ist gesplittert und beschädigt. Seine Augen können sich kaum noch fokussieren. Er ist dem Tode nah.>\n\nJedes Mal... wenn ich den Hammer einsetzen wollte... ist er mir einfach entglitten. Ich hätte Leben retten können. Aber nein... Ich...", sourceObjectiveStatus = "unverified-source-field" }
quests[79264] = { id = 79264, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Diese starken Hände", description = "<Berrund der Glänzende hustet trocken.>\n\nIch wusste, dass ich die Skardyn nicht ohne etwas Hilfe erledigen könnte. Ich dachte, nichts könnte mich aufhalten, wenn ich nur diesen magischen Hammer hätte. Ich musste ihn einfach haben, sonst wäre ich möglicherweise nicht der, der ich sein sollte.\n\nAber er rutschte mir immer wieder durch die Finger. Als wollte er nichts mit mir zu tun haben. Im schlimmsten Moment fiel er mir aus den Händen und jetzt... <Er hustet erneut.>\n\nEr gehört ganz eindeutig nicht mir. Hat er nie. Es... Es... tut mir leid.", sourceObjective = "Erlebt Moira Thaurissan.", completion = "Ich dachte, dieser Tag würde niemals kommen, weil mein Vater mir Furchtbrecher niemals gegeben hätte. Wahrscheinlich wollte er, dass es auf eine andere Weise geschieht.\n\nDoch jetzt habe ich ihn und ich werde dafür sorgen, dass er sicher zu ihm zurückkehrt.\n\nDoch zuerst müssen wir hier noch etwas erledigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[79265] = { id = 79265, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Furchtbrecher", description = "Die Skardyn haben den Betrieb hier in der Grollenden Einöde übernommen. Deswegen glaubte Berrund, er würde Furchtbrecher brauchen.\n\nWir erledigen diesen Auftrag, bevor ich Magni den Hammer zurückbringe.\n\nWas wäre ich für eine Königin, wenn ich mich nicht für das Wohl der anderen in Gefahr begäbe? Gehen wir dort hinein und retten wir so viele wir können.", sourceObjective = "Tötet Skardyn und rettet Irdene in der Grollenden Einöde mit der Hilfe von mit Moira Thaurissan.", completion = "Wenn auch nicht auf direktem Wege, haben wir doch das Leben dieser Irdenen verändert.\n\nBerrund hat hoffentlich etwas über wahres Heldentum gelernt. Aber das werden wir wohl noch rechtzeitig erfahren.\n\nBringen wir die Sache jetzt hinter uns.", sourceObjectiveStatus = "unverified-source-field" }
quests[79266] = { id = 79266, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Erbstück der Bronzebarts", description = "Nun, wir haben das uns gesetzte Ziel erreicht... und nicht nur das. Wir haben Furchtbrecher gefunden und mit seiner Hilfe Gutes getan.\n\nEs ist an der Zeit, ihn zu Magni zurückzubringen.\n\nHoffentlich hat Berrund hier etwas gelernt, doch ich fürchte, dass er sich bald wieder in Schwierigkeiten bringen wird. Hoffen wir einfach, dass es aus den richtigen Gründen und mit der richtigen Unterstützung passieren wird.", sourceObjective = "Trefft Euch mit Moira Thaurissan in Gundargaz.", completion = "Sehr seltsam. Ich verstehe, warum mein Vater diesen Hammer so sehr gemocht hat. Und was es bedeutet haben muss, wenn er ihn anderen anvertraute.\n\nFurchtbrecher hat irgendwie einen eigenen Willen. Und den will er durchsetzen.\n\nIch kann das nachvollziehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[79267] = { id = 79267, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wachs drauf, Topf runter", description = "Wenn Kerzen für die Koboldgesellschaft so wichtig sind, habe ich eine Idee, wie wir ihre Produktion stören könnten... oder zumindest dafür sorgen, dass unser Feind eine unangenehme Überraschung erlebt.\n\nNehmt das Glutbräu. Gebt etwas davon in die großen Wachsfässer, die die Kobolde auf dem Hügel vorbereiten. Es ist ein starker Sprengstoff und brennt sehr heftig, also versucht, nichts davon fallen zu lassen.\n\nDie Kerzen, die mit diesem Wachs hergestellt werden, dürften recht temperamentvoll lodern, sobald sie angezündet werden.", sourceObjective = "Sabotiert die Wachstöpfe im Hasenbau.", progress = "Versucht, nicht zu viel von den Dämpfen einzuatmen.", completion = "Hoffentlich verpasst ihnen das einen Dämpfer.\n\nDie Macht eines Anführers nimmt mal zu und mal ab. Angesichts all dieser Zerstörung nimmt die Macht des Kerzenkönigs eher ab.", sourceObjectiveStatus = "unverified-source-field" }
quests[79268] = { id = 79268, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gundrak-Überholspur", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
