quests[79273] = { id = 79273, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kaltarraaufstieg - Fortgeschritten", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[79274] = { id = 79274, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kaltarraaufstieg - Umgekehrt", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[79282] = { id = 79282, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das große Debüt", description = "Das Proszenium sieht großartig aus. Seid Ihr bereit für die Bühne?\n\nUnterstützt uns hinter den Kulissen, dann geben wir Euch die Chance, aufzutreten.\n\nNehmt Ihr diese Anweisung an?", sourceObjective = "Schließt ein Theatertruppenereignis im Proszenium ab.", progress = "Ich habe Euch noch nicht auf der Bühne gesehen, {name}. Mit Herumstehen gewinnt Ihr keine Fans.", completion = "Großartige Show! Eure Arbeit hat aus dem Proszenium eine hervorragende Bühne gemacht.\n\nKommt gern wieder vorbei. Wir brauchen immer Hilfe, auf und hinter der Bühne!", sourceObjectiveStatus = "unverified-source-field" }
quests[79295] = { id = 79295, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spritzt sie ab - Aktivieren" }
quests[79297] = { id = 79297, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nachtwache", description = "Xal'atath nutzt den Orden der Nacht für ihre Launen.\n\nIch habe gehört, wie sich einige Arathi über eine neue Propagandawelle beschwert haben, die in der Gegend von Mereldar aufgekommen ist. Findet heraus, was Ihr könnt, und meldet Euch damit bei Generalin Stahlstoß. Ich komme so schnell wie möglich nach.\n\nWir müssen sie von der Dringlichkeit dieser Bedrohung überzeugen.", sourceObjective = "Sammelt 8 Exemplare Propaganda des Ordens der Nacht.", progress = "Kann ich Euch irgendwie helfen, {name}?", completion = "<Generalin Stahlstoß liest sich die Propaganda durch, die Ihr mitgebracht habt.>\n\nIch muss mehr über diese Xal'atath erfahren.", sourceObjectiveStatus = "unverified-source-field" }
quests[79300] = { id = 79300, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Notizbuch", sourceObjective = "Helft Sophietta bei der Suche nach ihrem Notizbuch.", completion = "Edwyn hat es genommen? Natürlich. \n\nEr will unbedingt als nächster Kapitän ausgewählt werden, aber ich weiß, dass ich auf der Rangliste besser abschneide. Er hat nur eine Chance, wenn ich es nicht schaffe, meinen Bericht einzureichen. Wir müssen ihn zurückholen!", sourceObjectiveStatus = "unverified-source-field" }
quests[79301] = { id = 79301, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Höhenverein", description = "Ich habe Edwynn so satt. Seit dem ersten Tag, als wir hier angekommen sind, erzählt er allen, dass er als Kapitän ausgewählt werden wird.\n\nEr ist ein guter Flieger - sehr talentiert, und er kennt sich gut aus. Aber sein Ego hindert ihn daran, andere mit Respekt zu behandeln. Und er weiß, dass meine Noten und Flugbewertungen besser sind.\n\nDoch wenn ich meinen Bericht nicht einreichen kann, wird er zum nächsten Kapitän ernannt. Nehmt ihm den Bericht weg und bringt ihn mir!", sourceObjective = "Konfrontiert Edwyn mit dem Notizbuch.", progress = "Konntet Ihr es finden? Ich würde nur zu gerne Edwyns Gesichtsausdruck sehen...", completion = "Er hat es ins Tal geworfen und der WIND HAT ES MITGENOMMEN?", sourceObjectiveStatus = "unverified-source-field" }
quests[79302] = { id = 79302, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vom Winde verweht", description = "Ich kann nicht glauben, dass Edwynn meinen Bericht in den Wind geworfen hat. \n\nKönntet Ihr bitte so viele Blätter aufspüren wie möglich? Ich sehe mich auf dem Schulgelände um, Ihr übernehmt das Tal. \n\nDie Abgabefrist ist schon vorbei. Aber ich hatte ein paar richtig gute Einblicke in unsere Luftschiffkapazitäten. Wenn Direktor Fynch sie sieht, erlaubt er mir vielleicht, den Bericht trotzdem einzureichen.\n\nBringt mir alle Seiten, die Ihr finden könnt!", sourceObjective = "Bringt 10 Seiten aus Sophiettas Bericht zurück.", progress = "Ich hoffe, Ihr habt alle Seiten gefunden, {name}!", completion = "Ich wünschte, es würde besser aussehen. Ich bin zutiefst beschämt, es einzureichen, wenn Direktor Fynch mich überhaupt lässt.\n\nAber wir müssen es versuchen. Was zählt, sind die Ideen, und die sind weiterhin wahrhaftig.", sourceObjectiveStatus = "unverified-source-field" }
quests[79303] = { id = 79303, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein prinzipientreuer Direktor", description = "Ihr habt beim Einsammeln gute Arbeit geleistet. Ich habe ein paar Seiten gefunden, die hier umhergeflattert sind, also sollten wir alle haben. Übergeben wir den Bericht Direktor Fynch! Er sollte im Klassenzimmer anzutreffen sein.\n\nIch hoffe wirklich, dass er ihn annimmt. Er sagt, dass er keine Späteinreichungen annimmt, aber ich habe viele mildernde Umstände vorzuweisen. Und wenn er es nicht tut, würde ich Edwyn als neuem Kapitän unterstellt. Ich bin mir nicht sicher, dass ich das ertragen könnte, nach allem, was passiert ist.", sourceObjective = "Bringt Sophiettas Bericht zu Direktor Fynch.", completion = "Sophietta war eine hervorragende Schülerin. Ehrlich gesagt bin ich dieser Situation zu nahe, um eine unvoreingenommene Entscheidung treffen zu können. Aber die Situation ist auch zu uneindeutig, um die Arbeit ohne weitere Erwägung zu verwerfen.\n\nIch bin mir sicher, dass Ihr als Fremdling eine Entscheidung treffen könnt, die nicht davon beeinflusst ist, dass Ihr viele Monate mit diesen Schülern verbracht habt. Also kann ich Eurem Urteilsvermögen trauen. Ich weiß Eure Hilfe in dieser Situation zu schätzen, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[79304] = { id = 79304, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hilfspaket", description = "Meine Cousine Sophietta und ich sind zusammen nach Heilsturz gekommen, weil wir uns so gut verstanden haben. Seit unserer Ankunft haben wir beide jahrelang hier in Dunelles Güte gelebt. Aber letztes Jahr ist sie fortgegangen, um ihren Traum zu verfolgen, Luftschiffkapitänin zu werden oder zumindest einer Luftschiffbesatzung beizutreten.\n\nSie ist eine starke Person, aber ich weiß nicht, wie es ihr ergeht. Vor allem ohne die süßen Brötchen von Gastwirt Valrin! Im Lichtfunken, der Himmelsakademie, gibt es die nämlich nicht. Könnt Ihr ihr diese hier bringen und nachsehen, ob es ihr gut geht?", sourceObjective = "Bringt das Hilfspaket zu Sophietta Lynflayme in der Lichtfunken-Himmelsakademie.", progress = "Was ist das? Sind die für mich?", completion = "Es war sehr nett von Barahl, mir die hier zu schicken. Ihr könnt ihm ausrichten, dass es mir gut geht... Aber könntet Ihr mir zuerst bei etwas helfen?", sourceObjectiveStatus = "unverified-source-field" }
quests[79309] = { id = 79309, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Statusbericht", description = "Luftschiffe verschaffen der Arathiarmee die absolute Lufthoheit. Aber Straßen sind die Arterien von Reichen. Meine Späher beschützen und beleuchten die Gänge von Heilsturz für unsere Bürger.\n\nEine solche Patrouille hat sich mit dem Bericht zur östlichen Straße verspätet. Sucht meine vermissten Späher, orientiert Euch dabei an Rauch oder Flammen. Arathisoldaten wissen es besser, als sich zu lange in der Dunkelheit aufzuhalten.", sourceObjective = "Findet den vermissten Arathispähtrupp.", completion = "<Späher Wayshelm sieht Euch nicht in die Augen.>", sourceObjectiveStatus = "unverified-source-field" }
quests[79310] = { id = 79310, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Suche nach den Vermissten", description = "Bewacht unsere Wege, drängt das Dunkel zurück. Bringt diesem verdrehten Land Zivilisation. Alles im Namen unseres Reichs. Das ist die Mission der Arathiarmee. Eine Mission, die ich nicht länger erfüllen kann.\n\nIch habe Angst.\n\nIch kann nicht zurück in die Dunkelheit. Nicht, nach allem, was ich gesehen habe. Wenn Maevest oder einer meiner anderen Begleiter überlebt haben, werden sie sich die Gnade eines schnellen Todes wünschen. Und ich habe sie in diesem Schrecken zurückgelassen.\n\nSagt Hauptmann Wahrflamme, dass ihre Späher in der Dunkelheit starben, allesamt.", sourceObjective = "Sucht nach einem Mitglied von Wayshelms Gruppe.", progress = "<Späher Wayshelm starrt in die Flammen des Lagerfeuers.>", completion = "<Späher Wayshelm umklammert den Kompass fest und hebt endlich den Blick, um Euch anzublicken.>", sourceObjectiveStatus = "unverified-source-field" }
quests[79311] = { id = 79311, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eindämmen der Flut", description = "Die Straßen hätten beleuchtet sein sollen. Aber der Pfad war überwuchert, die Laternen dunkel. Es wimmelte, schäumte und stank vor Fäulnis. Alles geschah so schnell. Als wir uns der Gefahr bewusst wurden, griffen die Bestien uns bereits an. Die größte von ihnen war riesig und schwarz wie die Nacht.\n\nEs ist unsere Pflicht, Monster zu töten und die Dunkelheit zu vertreiben. Aber der Gedanke an eine Rückkehr erfüllt mein Herz mit Furcht. \n\nIch habe den Mut verloren. Aber Ihr, Fremdling, könnt das noch immer richtigstellen.", sourceObjective = "Tötet 12 Blähfaulstacheln oder Pilzinfizierer.", progress = "<Späherin Maevests Kompass glänzt im Licht des Feuers. Wayshelm hat ihn mit Bindfäden umwickelt und trägt ihn um den Hals.>", completion = "Ihr seid am Leben. Gesegnet sei die Heilige Flamme.", sourceObjectiveStatus = "unverified-source-field" }
quests[79312] = { id = 79312, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mähen der Massen", description = "Maevest und ich trennten uns von den anderen und flohen, ihre Schreie verfolgten uns. Übler Dreck löschte unsere Laternen, und wir stolperten in der Dunkelheit durch kniehohes Wasser. Ich hörte ein Platschen, als wäre sie gestolpert und hineingefallen, aber ich konnte mich nicht dazu durchringen, zurückzublicken.\n\nErst später fand ich die winzigen Bissspuren an meinen Knöcheln. Seid gewarnt, da ist etwas im Wasser.\n\nMir sind Wedel aufgefallen, die an den Tümpeln wachsen. Schwärmende Insekten nähren sich von ihrem kränklichen Nektar. Zerstört diese Pflanzen und hungert die Biester aus.", sourceObjective = "Schneidet 8 Faulnektarwedel ab.", completion = "<Späher Wayshelm nickt Euch anerkennend zu und lächelt grimmig.>\n\nIn der Dunkelheit wollen uns sogar die Pflanzen tot sehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[79313] = { id = 79313, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was im Dunkeln wächst", description = "Wir haben die Anweisung, niemals in die Dunkelheit zu gehen. Ein Licht mitzuführen, wohin wir auch gehen. Der Gedanke, über diesen Weg zurückzukehren, erfüllt mich mit Schrecken.\n\nAber Euer Mut strahlt ungetrübt, {name}. An Eurer Seite ist mein Weg hell erleuchtet.\n\nKein Verstecken mehr. Die in schwarzes Chitin gehüllte Bestie, die meine Freunde getötet hat, stirbt in dieser Höhle. Ich stehe Euch zur Seite.", sourceObjective = "Tötet Brachlandstachel.", completion = "Wayshelm hat mir alles berichtet.\n\nWir schulden Euch Dankbarkeit. Euch, und den Spähern, die ihre Leben für unser Reich gegeben haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[79315] = { id = 79315, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lord Harlbrand" }
quests[79316] = { id = 79316, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beschädigter Ernter" }
quests[79317] = { id = 79317, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Morkus Grimlock" }
quests[79318] = { id = 79318, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Narla Donnerhuf" }
quests[79319] = { id = 79319, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rasende Eulenbestie" }
quests[79320] = { id = 79320, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gorthak Grimmhauer" }
quests[79321] = { id = 79321, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Geschenk des Katalysators", sourceObjective = "Sprecht mit Antuka in Tyrhold.", completion = "Alle zwei Wochen erhaltet Ihr vom Katalysator genug Macht, um einen Ausrüstungsgegenstand zu erfüllen.\n\nHüter Tyr beobachtet uns wohl. Wo er auch sein mag, das ist kein Zufall.", sourceObjectiveStatus = "unverified-source-field" }
quests[79322] = { id = 79322, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ente gut, alles gut!", description = "Was zum... Was wollen diese ganzen Enten bloß hier? Irgendetwas hat sie verärgert. Sie haben fast mein wunderschönes Erbstück, mein goldenes Ei, umgestoßen!\n\nWir müssen uns dieser chaotischen Quaker entledigen, damit wir die Feier fortsetzen können. Ich werde dafür sorgen, dass sie nicht ins Gasthaus eindringen, könnt Ihr Euch darum kümmern, dass der Rest Leine zieht?", sourceObjective = "Verschreckt 10 Enten mithilfe des Horns des Hupens.", progress = "Zeigt den Enten, wer hier der Boss ist!", completion = "Diese Enten haben wahrlich ein Riesenchaos angerichtet. Danke, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[79323] = { id = 79323, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Quak-salberei", description = "Wir müssen dieser Enteninvasion ein Ende setzen.\n\nWährend ich ein paar der Nachzügler vom Gasthaus abhielt, tauchte ein ganzer Schwarm auf und hat sich mit einem Teil unserer Deko und einigen Eiern davongemacht. Mein kostbares Erbstück war unter den gestohlenen Stücken!\n\nBitte, {name}. Ich kann das dem diebischen Federvieh nicht durchgehen lassen. Ich kenne einen Magier in Sturmwind, der vielleicht weiß, wie man mit sowas umgeht.", sourceObjective = "Sprecht mit Emmery Fiske im Magiersanktum in Sturmwind.", progress = "Habt Ihr bereits mit Emmery gesprochen?", completion = "Keine Sorge, ich bin mir sicher, dass er eine gute Lösung finden wird. Wartet hier, ich glaube, ich sehe, wie sich ein Portal bildet.", sourceObjectiveStatus = "unverified-source-field" }
quests[79324] = { id = 79324, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zu den Wasserwerken", description = "Unser erstes Ziel besteht darin, die Wasserwerke wieder ans Laufen zu bringen. Wenn wir die Fabrik nicht mit Energie versorgen, hat alles andere keinen Zweck.\n\nTrefft Euch mit Dagran und ZZ-01-47, sobald Ihr dort eintrefft. Und versucht, die beiden aus der Schusslinie zu nehmen. Ich will Moira nicht beichten müssen, dass ihr Sohn in meiner Obhut verwundet wurde. Oder ihm noch Schlimmeres zugestoßen ist.", sourceObjective = "Trefft Euch mit Dagran und ZZ-01-47 an den Wasserwerken.", completion = "Das sieht hier ja aus! Ich glaube, Zet-Zet und ich bleiben hier, wo es trocken ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[79325] = { id = 79325, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schattenaderförderung", description = "Ich habe Zet-Zet zur Schattenaderförderstätte geschickt.\n\nIhrer Rückmeldung nach sieht es so aus, als ob es in dem Gebiet von Felswürmern wimmelt und es mit dieser... Entladung bedeckt ist. Ich habe sie etwas verbessert, während wir auf Euch gewartet haben.\n\nIch weiß nicht, wie effektiv das im Kampf sein wird, aber es sollte zumindest jeden schocken, der es auf sie abgesehen hat.", sourceObjective = "Trefft Euch mit ZZ-01-47 an der Schattenaderförderstätte.", completion = "<Zet-Zet piepst aufgeregt und anerkennend. Anscheinend ist Zet-Zet jetzt startbereit.>", sourceObjectiveStatus = "unverified-source-field" }
quests[79327] = { id = 79327, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der glitzernde Splitter", description = "<Dieser Kristallsplitter glitzert mit einem inneren Licht und fühlt sich warm an.\n\nOrsenth könnte Interesse daran haben, dieses Stück Erz zu untersuchen.>", sourceObjective = "Bringt den glitzernden Lehm zu Orsenth in der Nähe der Nibelgazmine.\n\nBereitgestellter Gegenstand:", completion = "Ein Kristallsplitter? Aus einer glitzernden Höhle? Wieso kommt mir das so bekannt vor?\n\n<Sie nimmt den Kristall in die Hände und sieht ihn sich genauer an.>\n\nDas kann nicht sein! Das ist der Verjüngungskristall, den ich vorhin erwähnt hatte! Wir hielten ihn für verschollen. Ein Wunder, dass ich ihn in Händen halten kann...\n\n<Sie seufzt schwer und sieht zu Munderut herüber.>\n\nWenn er doch unseren Verstand so heilen könnte, wie er auch andere Wunden heilt. Wir müssen das Gewölbe wieder flottmachen.", sourceObjectiveStatus = "unverified-source-field" }
quests[79328] = { id = 79328, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Botschaften und Gesandte", description = "Ich fürchtete das, was uns bei unserer Rückkehr hier erwarten würde. Nun erfüllt es mich aber mit Stolz, dass Ihr, trotz unserer zwangsläufigen Abwesenheit, Freundschaft mit den Irdenen schließen und Euch gegen die Neruber stellen konntet.\n\nMit Eurer Stärke werden wir siegen. Aber zuerst brauchen wir einen Plan, und dafür brauchen wir hier in Dornogal einen Gesprächsort.", sourceObjective = "Richtet die Botschaft Eurer Fraktion in Dornogal ein.", completion = "Wollt Ihr damit sagen, dass Ihr die ganze Zeit Inneneinrichter wart und mir etwas vorenthalten habt?\n\nSehr schön, {name}.\n\nIhr werdet meine Räumlichkeiten neu einrichten, wenn wir heimkehren. Ja, das werdet Ihr.", sourceObjectiveStatus = "unverified-source-field" }
quests[79329] = { id = 79329, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leuchtende Ernte" }
quests[79330] = { id = 79330, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ent-deckungen", description = "Nehmt diesen Trank, {name}. Damit sollte es Euch möglich sein, mit Euren gefiederten Freunden zu sprechen.\n\nAber ich übernehme keinerlei Verantwortung für Nebenwirkungen jedweder Art.", sourceObjective = "Nutzt den Trank, um Informationen aus 5 Enten herauszuholen.", progress = "Nur zu, unterhaltet Euch mit diesen Enten!", completion = "Was? Einige dieser Enten sind Druiden?\n\nSie werden mit ihren Störungen nicht durchkommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[79331] = { id = 79331, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wo Enten hausen", description = "Wir müssen herausfinden, wo die Enten die uns gestohlenen Waren verstecken! Und wer dieser geheimnisvolle Daetan ist, wenn wir schon dabei sind.\n\nIch konnte Emmery überreden, mir mehr von diesem Trank zu überlassen. Nehmt ihn und findet mein Erbstück!", sourceObjective = "Findet das Versteck der Enten.", progress = "Wo würde ich mich verstecken, wenn ich eine Ente wäre...", completion = "<Zinnia untersucht das Erbstück sorgfältig>\n\nHat da eine Ente dran rumgekaut? Das wird einiges an Muskelschmalz brauchen, um das wieder rauszupolieren!\n\nDanke für Eure Hilfe, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[79333] = { id = 79333, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Flotte trifft ein", description = "Vom Moment an, als wir auf dieser Insel gelandet sind, war uns kristallklar, dass wir Verbündete brauchen, um es mit Xal'atath aufzunehmen.\n\nJaina und Thrall sind losgezogen, um Verstärkung zu beschaffen, und Ihr und ich haben uns an die Arbeit gemacht, um zu sehen, was wir hier mit den Irdenen bewerkstelligen können.\n\nUnd ich finde, wir haben uns gut geschlagen, nicht wahr? \n\n<Moira lächelt Euch stolz an.>\n\nAber unsere Verstärkung scheint endlich einzutreffen. Die Friedensbewahrer haben Schiffe gesichtet, die in diese Richtung unterwegs sind. Seht nach und bestätigt die guten Nachrichten!", sourceObjective = "Haltet im Hafen nach einfahrenden Schiffen der Flotten von Allianz und Horde Ausschau.", completion = "Schön, dass Ihr wohlauf seid, {name}.\n\nDie Reise dauerte länger als erwartet. Die launische See hatte eigene Pläne, wie es scheint.", sourceObjectiveStatus = "unverified-source-field" }
quests[79335] = { id = 79335, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Noch eine Tradition", description = "Bevor ich abschalte, muss ich einen Gegenstand herstellen, der mir etwas bedeutet.\n\nAls Steingebundener habe ich in den Minen gearbeitet. Ich hatte eine selbst gemachte Laterne dabei, bis ich sie bei einem Einsturz verlor. Dann wurde ich frei.\n\nIch möchte eine neue Laterne schmieden, die mir in diesen letzten Augenblicken leuchtet.\n\nDie Laterne bestand aus einem Erz, das hier in kleinen Mengen gefunden wird. Ich hatte auch einen geladenen Kern in der Laterne. Ihr findet sie in den Sturmfängen, die in den Hügeln umherstreifen.\n\nSammelt die Materialien, dann schmiede ich die Laterne.", sourceObjective = "Sammelt 5 Stücke Erz und 5 geladene Kerne in der Nähe des Fallsprungaußenpostens.", progress = "Habt Ihr das Material, um das ich gebeten habe?", completion = "Das passt sehr gut!\n\nJetzt muss ich mich nur noch erinnern, wie man eine Laterne schmiedet.", sourceObjectiveStatus = "unverified-source-field" }
quests[79336] = { id = 79336, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schmiede der Erinnerungen", description = "Vor ihrer Deaktivierung stiegen wir Irdenen zur Erweckungsmaschine hinab, um unseren Zyklus zu erneuern. Doch selbst wenn sie noch funktionieren würde, würde ich meinen Zyklus nun unterbrechen und als der in Erinnerung bleiben, der ich bin.\n\n<Korgran seufzt tief.>\n\nDiese Hände sehen stark aus, doch sie werden mir mit jedem Augenblick schwerer. Die Steifigkeit in meinen Handgelenken und Ellbogen erlaubt es mir nicht mehr, etwas zur Schmiede zu tragen.\n\nBitte, gebt das richtige Material in die Schmiede – ich sage es Euch an.", sourceObjective = "Helft Korgran, seine Laterne zu schmieden.", progress = "Ich habe Euch doch gebeten, beim Schmieden der Laterne zu helfen, oder?", completion = "Das ist... hm. Sieht aus wie... Ich weiß es nicht mehr.\n\nAber die Laterne ist großartig!", sourceObjectiveStatus = "unverified-source-field" }
quests[79337] = { id = 79337, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die letzte Reise", description = "Die Laterne ist perfekt.\n\nGenug davon. Es ist soweit! Meine Erinnerung trübt sich ein. Wir müssen los. Urtago erwartet uns. Sie begleiten uns auf meiner letzten Reise nach Trauerhöhe, wo die Zeremonie stattfindet. \n\n<Korgran lächelt gezwungen.>\n\nNichts Großartiges. Wie gesagt, es ist vor allem symbolisch.\n\nMein Kopf wird schwer. Was wollte ich gerade tun? Ach ja, Urtago treffen!", sourceObjective = "Wartet auf Korgran und trefft Euch dann mit Urtago draußen am Fallsprungaußenposten.", completion = "{name}, wir müssen Korgran finden! Wenn er sich weiter so anstrengt, schaltet er mitten im Nirgendwo ab.\n\nIn seinem Zustand ist er draußen nicht sicher. Er wäre eine leichte Beute für Sturmfänge oder sogar Kobolde.", sourceObjectiveStatus = "unverified-source-field" }
quests[79338] = { id = 79338, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der verirrte Irdene", description = "Furchtbar! Ich wusste, dass wir ihn besser hätten im Auge behalten sollen.\n\nVerwirrung ist das letzte Symptom vor dem Abschalten. Unsere Erinnerung ist endlich und wird überschrieben. Je mehr sich ein Irdener anstrengt, desto schneller wird seine Energie verbraucht, und er verliert Erinnerungen. Korgran fürchtet sich bestimmt, weil er nicht weiß, wo er ist.\n\nIch muss Steine im Kopf haben!\n\n{name}, ich glaube, ich habe ihn nach Osten in den Wald gehen sehen. Wir treffen uns dort an der Straße!", sourceObjective = "Helft Urtago, Korgran zu finden.", progress = "Habt Ihr eine Spur von Korgran gefunden?", completion = "Oh nein, Korgrans Zustand verschlechtert sich rapide.\n\nIhm die Laterne zu zeigen, war eine gute Idee.\n\nDanke, dass Ihr ihn zu mir geführt habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[79339] = { id = 79339, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wandelbare Tradition", description = "Ein freier Irdener kann nicht zum Kernweg zurückkehren, deshalb haben wir Trauerhöhe. Aber wenn ich Korgran so sehe und an unsere letzte Unterhaltung denke...\n\nIch bin vielleicht noch nicht die Verwalterin von Trauerhöhe, aber bei Korgrans Zustand muss ich die Verantwortung übernehmen.\n\nAls Freie machen wir unsere eigenen Regeln. Wenn er also nicht in Trauerhöhe stehen will, sondern lieber am Meer, dann kann Verwalter Korgran das tun.\n\n{name}, wir treffen uns an der Küste südöstlich von hier.", sourceObjective = "Trefft Urtago und Korgran an der Küste.", completion = "Der Spaziergang hat ihm gefallen, hat ihn aber auch sehr angestrengt.\n\nKorgran erkennt mich kaum noch.", sourceObjectiveStatus = "unverified-source-field" }
quests[79340] = { id = 79340, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Werkzeug der Erklärung", description = "Als freie Verwalter haben wir eine Tradition für die Übergabe des Mantels vom Meister an den Lehrling.\n\nSymbolisch natürlich.\n\nDazu braucht Korgran ein Horn.\n\nEr steht mir dann gegenüber, bläst in das Horn, und der Ton symbolisiert die Weitergabe des Mantels des Verwalters von Trauerhöhe an mich.\n\nWestlich von hier habe ich Schieferhörner gesehen. Bitte bringt mir einige ihrer Hörner. Dann wähle ich ein passendes aus.", sourceObjective = "Sammelt 4 Makellose Hörner an der Rastlosen Mündung.", progress = "Denkt daran, dass die Hörner makellos sein müssen.", completion = "Sie sind wunderschön!\n\nEs tut mir leid um die Schieferhörner, aber es gibt ja viele von ihnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[79341] = { id = 79341, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reinigende Asche", description = "Die Freien verfügen über eine symbolische Reinigungszeremonie. Wir führen sie vor einer Abschaltung durch.\n\nDas ist ein symbolischer Reinigungsprozess. Dafür benötigen wir Aschenbruch, eine Blume, die auf der Insel wächst. Wir leiten den Rauch der verbrannten Blumen durch die Risse und Spalten in unseren Körpern, um symbolisch Unreinheiten zu beseitigen.\n\nDanach können wir unsere letzten Augenblicke genießen.\n\n<Urtago schaut Korgran an. Ihre Hand liegt auf ihrer Brust. Ihr Kopf sinkt.>", sourceObjective = "Sammelt 6 Aschenbruch an der Rastlosen Mündung.", progress = "Habt Ihr die Blumen, {name}?", completion = "Danke, {name}, ich bereite sie jetzt für das Ritual vor.", sourceObjectiveStatus = "unverified-source-field" }
quests[79342] = { id = 79342, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Als er geht", description = "Es ist an der Zeit für die Zeremonie, {name}.\n\nBitte stellt die Schale mit Aschenbruch neben Korgran und gebt ihm dann das Horn.\n\nNach Abschluss der Zeremonie bin ich dann die neue Verwalterin. Dann muss ich mich von meinem Freund ein für alle Mal verabschieden.\n\nKorgran wird sich, in dem Wissen, dass ich an seinem Lieblingsort bei ihm bin, friedlich abschalten. Das wünsche ich mir auch für mich so, wenn meine Zeit kommt.\n\nMein Kern ist zwar Matsch, aber es ist mir eine große Ehre, hier neben ihm zu stehen... und neben Euch.", sourceObjective = "Helft Urtago und Korgran bei der Durchführung der Zeremonie.", progress = "Das ist ein bittersüßer Moment.", completion = "Welch Ehre, hier zu sein. Bei solch einem Ereignis.\n\nIhr wart ein Teil davon und ich weiß, dass sich in seinem tiefsten Inneren, Korgrans Kern, eine lebhafte Erinnerung an Euch eingebrannt hat, {name}.\n\nHabt Dank.", sourceObjectiveStatus = "unverified-source-field" }
quests[79343] = { id = 79343, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schnüffeln jeden Tag", description = "Vielleicht haben die Kobolde von Gundargaz Interesse an diesem Seltsamen Wachsklumpen.", sourceObjective = "Bringt den Seltsamen Wachsklumpen zu Nagerlein in Gundargaz.", progress = "Ihr was Gutes erschnüffelt?", completion = "Middels immer brauchen mehr Wachs für Projekt. Tauscht größere, glänzendere Rubine ein, wenn viele haben. Schickere Sachen für Hilfe bekommen.\n\nWeiter schnüffeln. Weiter tauschen.", sourceObjectiveStatus = "unverified-source-field" }
quests[79344] = { id = 79344, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Städtische Odyssee", description = "Habt Ihr schon gehört, {name}?\n\nEine Menge Leute aus der Stadt wollen uns helfen und unseren Angriff auf die Neruber und Xal'atath unterstützen. Ich denke, es lohnt sich, sie anzusprechen und zu sehen, wie sie uns helfen können.\n\n Je mehr Unterstützung wir bekommen, desto besser.", sourceObjective = "Fragt in Dornogal nach zugesagter Unterstützung im kommenden Konflikt.", completion = "Habt Dank, {name}. Je mehr an Bord kommen, um uns zu helfen, desto größer wird unser Erfolg.\n\nDoch wir werden gar nichts erreichen, wenn unsere Kampfkraft nicht ausreicht.\n\nDie Irdenen sind in keiner guter Verfassung. Alleria könnte uns in dieser Hinsicht allerdings helfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[79346] = { id = 79346, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Da habt Ihr was zum Beißen", description = "Es ist nicht einfach, hier zu angeln, besonders wenn die gruseligen Geräusche der Dunkelheit deine Nerven strapazieren.\n\nIch habe angefangen, die Dämmerstiele der nahen Pflanzen zu kauen. Sie sind süß und zäh, halten den Kiefer beschäftigt und helfen mir, Zeit totzuschlagen!\n\nWenn Ihr mir helfen und mit Eurem Flugreittier ein paar Dämmerstiele sammeln könntet, wäre ich Euch zutiefst dankbar.", sourceObjective = "Sammelt 20 Dämmerstiele von den höchsten Pflanzen, die in der Dunkelheit wachsen.", progress = "Habt Ihr genug gesammelt?", completion = "Bei Euch sah das so leicht aus. Normalerweise brauche ich eine Stunde, um eine dieser Pflanzen zu erklimmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[79349] = { id = 79349, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Entrepreneur AG", description = "Okay, ich bin beeindruckt. Ihr seid offiziell mein Münzchamp! Das ist wie eine Art Champion, nur dass ich Euch dafür bezahle, bestimmte Dinge zu tun. Ein Söldner, aber mit besserer Vermarktung.\n\nIhr solltet meinen Geschäftspartner Zocknudel kennenlernen. Er wickelt gerade mit seinen eigenen Münzchamps ein paar Geschäfte mit den Niffen in Mmarl ab. Möglicherweise hat er noch mehr Arbeit für Euch, ich würde allerdings davon abraten, etwas von ihm zu kaufen, wenn er Euch etwas andrehen will.\n\nIhr findet Mmarl weiter Richtung Osten. Folgt einfach Eurer Nase, man riecht es schon aus der Ferne.", sourceObjective = "Findet Zocknudel in Mmarl.", completion = "Skedgit hat da draußen tatsächlich was gefunden? Sie hatte schon immer ein gutes Gespür fürs Geschäft.", sourceObjectiveStatus = "unverified-source-field" }
quests[79351] = { id = 79351, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stufe 25" }
quests[79352] = { id = 79352, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stufe 24" }
quests[79354] = { id = 79354, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Maschinenflüsterer", sourceObjective = "Wohnt dem Gespräch zwischen Moira und Sprecherin Brinthe in Gundargaz bei.", completion = "Ein neuer Tag in den Schallenden Tiefen bricht an.", sourceObjectiveStatus = "unverified-source-field" }
quests[79355] = { id = 79355, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gefangenenschutz", description = "Die Bestien haben sich unsre Leute geschnappt! Haben sie einfach weggezerrt, als wir nach der Flucht zum erst'n Mal eine Verschnaufpause hatt'n!\n\nWir sind dies'n Nerubern gerade so entkomm'. Wir können uns nich' erlaub'n, noch mehr Leute zu verlier'n.\n\nSucht in Stütznest Vosh. Da kamen all die Bestien her. Wenn wir Glück haben, sind unsre Leute noch am Leb'n.", sourceObjective = "Findet 4 Expeditionsmitglieder.", completion = "Ihr habt getan, was Ihr konntet. Ich steh in Eurer Schuld. Wir ehr'n Jetis Andenk'n, indem wir uns ums Nest kümmern.", sourceObjectiveStatus = "unverified-source-field" }
quests[79356] = { id = 79356, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feuerfungizid", description = "Nennt's 'ne wilde Vermutung, aber diese Spor'n, die da aus den Funguskapseln komm', und die, die all die Bestien beeinfluss'n, sin' irgendwie miteinander verbund'n.\n\nWenn wir die Funguskapseln zerstör'n, versetzt das der Kontrolle, die die Fungianer über die Bestien haben, vielleicht 'nen Dämpfer.\n\nNehmt diese Anti-Fungus-Feuerbomb'n und zündet so viele Fungussporenkapseln an, wie Ihr könnt.", sourceObjective = "Verbrennt 8 Fungussporenkapseln.", completion = "Ausgezeichnete Arbeit. Das wird diese Bestien in Schach halt'n.", sourceObjectiveStatus = "unverified-source-field" }
quests[79357] = { id = 79357, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hut ab", description = "Dass Aemara von 'nem großen Fungianer gesproch'n hat, der Funguskapseln pflanzt, macht mir Sorgen. Irgendwas muss in der Höhle sein.\n\nWir können nich' einfach abwart'n, bis die Fungianer mit 'nem Nest fremdgesteuerter Bestien angreifen. Wir müssen den Plan zurechtstutz'n, ehe er noch gedeiht.\n\nGeht zum Stütznest Vosh und tötet dies'n Anführer der Fungianer!", sourceObjective = "Tötet Agaricus Eiterblüte.", completion = "Die Pläne des Anführers der Fungianer sind vereitelt und das Lager wieder sicher. Habt Dank.", sourceObjectiveStatus = "unverified-source-field" }
quests[79367] = { id = 79367, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Nebb in Not", description = "Ihr! Ihr keine Spinne. Bitte helfen, bevor Spinnen kommen wieder.\n\nNebb Zirpender Bau kennen. Hat dort nie Spinnen gesehen. Fressen Larven, fressen Kobolde. Aber Spinnen finstere Dinge von finsterem Ort. Hassen Licht.\n\nDarf Posten nicht verlassen. Ihr Kerzen nehmen, ja? Barrikade erleuchten. Spinnen fernhalten.", sourceObjective = "Sammelt das Bündel Kerzen ein und platziert Kerzen entlang der Barrikade.", progress = "Fernhalten Dunkel. Fernhalten Spinnen.", completion = "Gut. Wir vorerst sicher.", sourceObjectiveStatus = "unverified-source-field" }
quests[79368] = { id = 79368, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gift mit Gift bekämpfen", description = "Licht gut, aber mehr zu tun.\n\nSpinnen von überall gekommen. Nebb schnell, Nebb hört sie. Aber Freund Meckermaul... gebissen worden. Jetzt krank.\n\nNebb vielleicht wissen, wie Gift zu Arznei machen. Biss durch Biss heilen.\n\nIhr mir Gift bringen. Schnell!", sourceObjective = "Sammelt 12 Unterkrabblergift.", progress = "Ihr habt Gift?", completion = "Ja, böses Gift perfektes Heilmittel ergeben.", sourceObjectiveStatus = "unverified-source-field" }
quests[79369] = { id = 79369, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beschützen der Ernte", description = "Junger Nebb nie weiter als eigene Schnauze gesehen. Wenn Ernte verloren, viele Kobolde verloren! Nicht nur Meckermaul.\n\nNix Zeit verschwenden. Kobolde verhungern, wenn Spinnen mampfen Laven und Eier.\n\nIhr uns retten, Eier sammeln. So viele wie tragen können, bevor Spinnen alle schnappen.", sourceObjective = "Sammelt 20 Larveneier ein.", progress = "Holt Eier, wir Ernte retten.", completion = "Viele verloren! Mit diesen nächste Larvensaison möglich.", sourceObjectiveStatus = "unverified-source-field" }
quests[79370] = { id = 79370, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Wickel für Gift", description = "Bisschen Gift, bisschen Wachs...\n\n<Nebb greift in seinen Beutel und überreicht Euch eine Handvoll stechend riechendes, dickes Wachs.>\n\nJa, ja, müsste klappen. Bester Wickel, Familienrezept. Und jetzt schnell Meckermaul geben. Er sich sofort besser fühlen.", sourceObjective = "Wendet Nebbs Wickel bei Meckermaul an.", progress = "Wickel ihn sofort gesund machen.", completion = "Nix funktionieren! Er schlimmer! Aber warum?", sourceObjectiveStatus = "unverified-source-field" }
quests[79371] = { id = 79371, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine königliche Kur", description = "Wickel nix funktionieren! Wachs richtig, Gift falsch?\n\nJa... Ja! Stärkste Arznei stärkstes Gift brauchen. Nebb hat Krabbler gesehen. Sie Königin ist in Rot und Schwarz, zu groß, Kobolde uninteressant für sie. Königin wittern leckere Larven und krabbelt in Höhle.\n\nIhr müsst hinterher. Königliches Gift sammeln. Bitte, Meckermaul nur wenig Zeit.", sourceObjective = "Beschafft Königin Rickitickas Toxin, um daraus einen neuen Wickel für Meckermaul herzustellen.", progress = "Königinnengift muss funktionieren.", completion = "Es funktionieren! Er nix mehr grün. Danke, danke für helfen retten Freund Meckermaul.", sourceObjectiveStatus = "unverified-source-field" }
quests[79372] = { id = 79372, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Strohhalm der Hoffnung", description = "<Die tote Brutmutter liegt gekrümmt um ein einzelnes Ei. Sie hat ihr Leben geopfert, um es vor den Spinnen zu retten.\n\nIhr solltet es Nebb bringen. Er und die anderen Larvenpfleger wissen, was damit zu tun ist.>", sourceObjective = "Bringt das Ei zu Nebb.", progress = "Was das ist, noch ein Ei?", completion = "Das nicht irgendein Ei. Mutterei.\n\n<Nebb nimmt das Ei entgegen. Er hält es ehrfürchtig hoch.>\n\nDamit Laven nicht nur überleben. Sondern aufblühen. Danke. Wir es beschützen.", sourceObjectiveStatus = "unverified-source-field" }
quests[79379] = { id = 79379, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Befehle des Kapitäns: Keine Beute, kein Zaster" }
quests[79380] = { id = 79380, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verbannung der Sumpfbestie" }
quests[79381] = { id = 79381, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Befehle des Kapitäns: \"X\" markiert die Stelle" }
quests[79382] = { id = 79382, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Befehle des Kapitäns: Plünderstudie" }
quests[79383] = { id = 79383, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Netz der Manipulation - Aktivieren" }
quests[79432] = { id = 79432, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Zeit ist gekommen", description = "Welch glücklicher Zufall, Euch jetzt hier zu treffen. Ich benötige Eure Hilfe.\n\nNicht alle Ewigen haben gesehen, was Nozdormu mir gezeigt hat. Nicht alle würden zustimmen, selbst wenn sie es gesehen hätten. Archaios ist einer dieser Kritiker. Er muss beseitigt werden.", sourceObjective = "Tötet Archaios, den Konstrukteur.", progress = "Die anderen Ewigen gefährden unsere Mission. Wir können nicht zulassen, dass sie in den Zeitwegen Chaos stiften.", completion = "Leichtsinnig. Sie haben die Zeitfäden aufgetrennt!", sourceObjectiveStatus = "unverified-source-field" }
quests[79433] = { id = 79433, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Rat einer Expertin", description = "Bringt diese Spule zu Moratari. Vielleicht wird sie aus diesem Relikt schlau.", sourceObjective = "Sprecht mit Moratari.\n\nBereitgestellter Gegenstand:", completion = "Was habt Ihr da? Aus diesem Artefakt strömt die temporale Macht ja geradezu heraus!\n\n<Moratari lehnt sich vor, um besser sehen zu können.>\n\nAha! Sogar noch brillanter, als ich dachte! Es assimiliert die latenten temporalen Signaturen von aufgetrennten Opfern...\n\nEntschuldigt, ich bin ein wenig zu schnell, ich weiß. Lasst es mich erklären.", sourceObjectiveStatus = "unverified-source-field" }
quests[79434] = { id = 79434, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Doppelt gewebt hält besser", description = "Die anderen Ewigen gehen nicht so umsichtig mit der Zeitlinie um. In ihrem waghalsigen Widerstand gegen unsere Bemühungen haben sie der Zeit Risse zugefügt.\n\nWir können die Zeitwege nicht einfach so flicken, aber wir können die losen Fäden vielleicht noch zu anderen Zwecken nutzen.\n\nHolt Euch die Zeitfäden von unseren Feinden zurück, dann werden wir Euch einen Umhang weben, der des ewigen Drachenschwarms würdig ist.", sourceObjective = "Sammelt 3 Zeitfäden von ewigen Verheerern.", progress = "Als verantwortungsbewusste Gelehrte ist es unsere Pflicht, hinter uns aufzuräumen... und hinter anderen.\n\n<Moratari wirft den Verheerern in der Ferne einen genervten Blick zu.>\n\nWir können nicht zulassen, dass verstreute Fäden weiterhin Zeitanomalien hervorrufen.", completion = "Ausgezeichnet. Jetzt brauchen wir nur noch etwas, um sie zusammenzuhalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[79435] = { id = 79435, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wie viel Uhr ist es bei Euch", description = "Horos, unser Antiquitätensammler, sollte ein Chronoabzeichen haben, das Ihr nutzen könnt, um die Zeitfäden, die Ihr gesammelt habt, zusammenzufügen.\n\nMit einem Chronoabzeichen kann Momentus aus den Fäden einen mächtigen Umhang weben, den Ihr tragen könnt!", sourceObjective = "Erwerbt ein Chronoabzeichen von Horos und sprecht dann mit Momentus.", progress = "Dieser Umhang kann lose Zeitfäden absorbieren und sie seiner eigenen Magie hinzufügen. Die Aussicht auf ewige Macht ist verlockend, nicht wahr? Lasst sie Euch nur nicht zu Kopf steigen.\n\nLasst sie stattdessen in Euren Mantel einfahren!\n\n<Moratari kichert.>", completion = "Wunderbar. Probiert ihn an.\n\nMithilfe der Zeitmagie in diesem Umhang wird es Euch möglich sein, die verstreuten Zeitfäden zu sehen und einzusammeln.\n\nEs gibt keine Beschränkung bei der Anzahl der Fäden, die Möglichkeiten sind endlos!", sourceObjectiveStatus = "unverified-source-field" }
quests[79437] = { id = 79437, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Knoten im Moment", description = "Diese Zeitanomalien geraten langsam außer Kontrolle. Unsere Forschung trennt normalerweise die Zeitlinie nicht so weit auf. Ich denke, dass die anderen Ewigen die Schuld hieran tragen.\n\nNutzt diesen Chronostabilisierer, um die zerfetzten Risse zu schließen.\n\nSeid auf der Hut: Dadurch können kurzfristig noch mehr Anomalien entstehen. Ich vertraue darauf, dass Ihr wisst, wie mit diesen umzugehen ist.", sourceObjective = "Nutzt den Chronostabilisierer, um 3 Zeitrisse zu schließen.", progress = "Jeder Moment führt uns zu einer neuen Möglichkeit. Mit jedem Kampf lernen wir und ändern uns.", completion = "Veränderungen erzeugen Veränderungen. Das ist die Philosophie der Ewigen. Es ist unsere Pflicht, auszuwählen, welche Veränderungen es wert sind, bewahrt zu werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[79438] = { id = 79438, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ewiges Leben erschwert das Abschiednehmen", description = "Wir müssen uns um eine letzte Anomalie kümmern, bevor wir die Geschichte von Pandaria studieren können.\n\nHelft uns, den Zeitweg zu stabilisieren und unsere Mission zu sichern.", sourceObjective = "Besiegt Eratus, das entwebte Paradoxon.", completion = "Habt Dank für Eure Hilfe im Kampf, {name}. Eternus wird sicherlich eine Verwendung für Euch haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[79440] = { id = 79440, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kriegserinnerungen", description = "Unsere Angelegenheiten hier sind gesichert. Jedenfalls für den Augenblick!\n\nDie Zeit ist gekommen, dass Ihr Eure Reise in die Vergangenheit antretet, damit wir beobachten können, wie sich die Geschichte entwickelt hat.\n\nSprecht mit Eternus, wenn Ihr noch letzte Fragen zu unserer Mission haben solltet. Sie kann Euch zeigen, wie diese Geschehnisse begannen.", sourceObjective = "Bittet Eternus, Euch die Geschehnisse der Vergangenheit zu zeigen.", completion = "Viel Erfolg, {name}. Wir werden Euch beobachten.", sourceObjectiveStatus = "unverified-source-field" }
quests[79448] = { id = 79448, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flugstein, Flugstein, jeder muss entdeckt sein", description = "Es ist so aufregend, in Valdrakken zu sein! Cuzolth und ich waren noch nie hier. Und es bietet wirklich alles, was wir uns erhofft hatten. Einige der anderen haben sich sogar vorgestellt. Sie haben uns tatsächlich für unsere Forschung zu den Flugsteinen und Wappen gedankt! Das ist der Traum jedes Forscherherzens!\n\nDeshalb brauche ich noch einmal Eure Hilfe. Könntet Ihr einige Flugsteine und ein neues Teil Abenteuerausrüstung auftreiben? Damit könnt Ihr dann zu Cuzolth kommen, um es aufzuwerten. Das würde uns wirklich helfen, unsere neue Position hier zu festigen.", sourceObjective = "Besorgt 50 Flugsteine, indem Ihr einzigartige Kreaturen besiegt, Dungeons und Schlachtzüge meistert, Weltquests abschließt oder Schätze plündert. Sprecht danach mit Cuzolth und wertet einen Ausrüstungsgegenstand aus Saison 4 unter Einsatz von Flugsteinen auf.", progress = "Es hat keine Eile. Aber vielleicht beeilt Ihr Euch trotzdem ein wenig...", completion = "Mein Freund! Ihr seid wie ein stützender Aufwind im Flug! Bitte nehmt dieses Zeichen meiner Dankbarkeit an.", sourceObjectiveStatus = "unverified-source-field" }
quests[79453] = { id = 79453, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erweckte Wappen, unbegrenzte Möglichkeiten", description = "Eure Hilfe ist immer willkommen, und jetzt könnt Ihr Eure niedrigstufige Ausrüstung gleich hier aufwerten.\n\nAllerdings wisst Ihr vermutlich schon, dass Flugsteine auch ihre Grenzen haben. Um mächtige Abenteuerausrüstung aufzuwerten, braucht Ihr erweckte Wappen. Genau wie Flugsteine könnt Ihr diese Wappen bei vielen verschiedenen Aktivitäten erlangen. Erweckte Wappen gibt es in vier Stufen: je gefährlicher die Aufgabe, desto höher die Stufe des Wappens, das Ihr dafür bekommt.\n\nBringt mir doch 15 erweckte Wappen des Welpen, und wir können Euch helfen, Eure Ausrüstung weiter aufzuwerten.", sourceObjective = "Besorgt 15 erweckte Wappen des Welpen, indem Ihr einzigartige Kreaturen besiegt, Dungeons und Schlachtzüge bezwingt, Weltquests abschließt oder Schätze plündert. Kehrt dann zu Vaskarn in Valdrakken zurück.", completion = "Das ist wunderbar. Ich freue mich für Euch, dass Eure Macht so anwächst!", sourceObjectiveStatus = "unverified-source-field" }
quests[79469] = { id = 79469, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lauernd in der Tiefe" }
quests[79470] = { id = 79470, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gewässer des Krieges" }
quests[79471] = { id = 79471, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trübsand" }
quests[79475] = { id = 79475, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sturm auf dem Hügel", description = "Bevor wir die Leitung verwenden, um die Sturmkrähen zu beschwören, müssen wir sie wieder aufladen. Es gibt andere, sanftere Möglichkeiten, dies zu tun, aber ... wir müssen mit dem arbeiten, was zur Hand ist.\n\nDer Weg zum Gipfel ist voller feindlicher Elementare, die vom Sturm ausgestoßen wurden. Wenn wir sie auf ihre Ebene zurückschicken, können wir ihre Restenergie einfangen und die Leitung wieder mit Energie versorgen.\n\nWährend Ihr daran arbeitet, die Leitung aufzuladen, bereiten wir das Ritual auf dem Gipfel vor.", sourceObjective = "Ladet die Leitung mit Elementarmagie auf.", progress = "Habt Ihr die Leitung fertig aufgeladen?", completion = "Die Leitung! Spürt Ihr das auch? Sie brummt, nein, sie singt praktisch vor Energie. \n\nDieses Lied habe ich schon einmal gehört, spät nachts in der Brutstätte des Sturmhorts. Wenn die Stürme kamen und Blitze über der Bucht zucken, antworten die Krähen genauso. \n\nHört Ihr es?", sourceObjectiveStatus = "unverified-source-field" }
quests[79476] = { id = 79476, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Ruf hören", description = "Dieser Ort zieht Irdene von der ganzen Insel an. Ein seltsamer Zufall, dass Ihr gerade jetzt auftaucht.\n\nVielleicht liegt es daran, dass Baelgrim weg ist oder... eine neue Sturmwehr kommt. Oder es könnte einfach nur am Luftdruck liegen...\n\nEgal! Wir haben später genug Zeit, um wilde Theorien zu spinnen. Jetzt müssen wir den Pilgern helfen, die törichterweise versucht haben, den Gipfel unvorbereitet zu erreichen. Wir dürfen uns keine Gedanken um sie machen, während wir versuchen, die Sturmkrähen zu beschwören.", sourceObjective = "Helft 8 gestrandeten Pilgern auf dem Berg.", progress = "Diese irdenen Pilger scheinen dringend den Gipfel erreichen zu wollen. Ich hoffe, wir können sie schützen.", completion = "Wenn der Sturm die Irdenen hierher gerufen hat, spielen sie dann eine Rolle bei den bevorstehenden Ereignissen? \n\nWir haben sie erst einmal in die Höhle in Gipfelnähe geschickt. Ich habe keine Ahnung, was sie - oder uns - als Nächstes erwartet.", sourceObjectiveStatus = "unverified-source-field" }
quests[79477] = { id = 79477, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Streuner", description = "Kurdran Wildhammer ist hergekommen, um den neuen Sturmreitern Flugmanöver beizubringen. Thrall sagt, sein Klan reitet auf Greifen, so wie die Sturmreiter auf Sturmkrähen reiten, also sollte er uns eine große Hilfe sein. \n\nLeider scheinen sich einige unserer neuen Rekruten, ähm, mit ihren Sturmkrähen davongemacht zu haben. Ich wollte ihnen die Gelegenheit bieten, eine Bindung zueinander aufzubauen, aber nun müssen sie wieder heimkommen.\n\nWürdet Ihr sie vielleicht für mich zusammentrommeln? Thrall und ich bereiten etwas Besonderes für diese Anfängerlektionen vor.", sourceObjective = "Trommelt die versprengten Rekruten zusammen.", progress = "Habt Ihr die versprengten Neulinge schon gefunden?", completion = "Dann mal los! Danke, dass Ihr alle zusammengetrommelt habt. Wir wollen mit der offiziellen Flugausbildung anfangen. Da können wir keine Nachzügler gebrauchen. \n\nMal sehen, was diese Sturmkrähen - und die Irdenen - so draufhaben.", sourceObjectiveStatus = "unverified-source-field" }
quests[79480] = { id = 79480, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Respekt erweisen", description = "Bitte verzeiht meine Abwesenheit. Es war nie meine Absicht, die Sturmreiter im Stich zu lassen, weder damals noch heute. Aber ich musste hierher kommen, um Baelgrim meinen Respekt zu erweisen.\n\nLeider treiben sich diese verdammten Neruber immer noch hier herum. Ich glaube, sie suchen nach etwas, aber ich weiß nicht, wonach. Was auch immer ihre Motive sind, ich kann nicht zulassen, dass sie dort herumlungern, wo Baelgrim gefallen ist.", sourceObjective = "Tötet die Nachzügler der Neruber.", progress = "Ich weiß nicht, wen oder was diese Neruber suchen, aber sie entweihen diesen Ort mit ihrer Anwesenheit. Vertreibt sie.", completion = "Das ist ein Geschenk. Baelgrim mag zwar tot sein, aber seine Sturmkrähe ist bereit, seinen Kampf fortzuführen. Es ist lange her, dass ich eine solch starke Verbindung gespürt habe. Solche Entschlossenheit. Ich habe nicht vor, mich noch einmal abzuwenden.", sourceObjectiveStatus = "unverified-source-field" }
quests[79481] = { id = 79481, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Verängstigten Pflege", description = "Alles so schnell passieren. Erst wir einfach sammeln Eier und Larven. Dann Spinnenschwarm kommen.\n\nNebb mich herziehen. Viele andere gefangen. In Netzen gefangen und bald Festschmaus. Müssen Larvenpfleger retten.\n\nWir Pfleger, keine Kämpfer. Freunde nix Mittagessen werden dürfen.", sourceObjective = "Rettet 6 verängstigte Larvenpfleger.", completion = "Aha, Larvenpfleger frei! Sie überleben für nächste Ernte.", sourceObjectiveStatus = "unverified-source-field" }
quests[79489] = { id = 79489, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Edelsteine der Macht", description = "Ihr habt einen Edelstein gefunden, der Eure Kampffähigkeiten verbessert, wenn er in einem prismatischen Sockel in Eurer Brust- oder Beinrüstung gesockelt wird.\n\nSockelt diesen gesprungenen tödlichen Saphir in Eurer Ausrüstung, um Eure kritische Trefferchance zu erhöhen.Ihr erlernt:", sourceObjective = "[Mit Umschalt und Rechtsklick auf Eure Brust- oder Beinrüstung klicken und den abgesplitterten tödlichen Saphir sockeln.]", sourceObjectiveStatus = "unverified-source-field" }
quests[79504] = { id = 79504, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tropfi ohne Kerze", description = "Versammelt Euch, Weichfüße, Großmutter Krickelkrakel erzählt Geschichte.\n\nGeschichte darüber, was geschah, als Tropfi ihre Kerze vergaß.\n\nAls Tropfi, kleine Weichfüßin wie Ihr, sich vom Stamm entfernte...", sourceObjective = "Erlebt Großmutter Krickelkrakels Geschichte noch einmal.", progress = "Ihr auch zuhören. Vielleicht noch was lernen.", completion = "Niemals Kerze vergessen. Jeder kleine Kobold lernen müssen.", sourceObjectiveStatus = "unverified-source-field" }
quests[79505] = { id = 79505, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mampf und der Einsturz", description = "Setzt euch, Schluss mit Reden, Großmutter Krickelkrakel erzählt Geschichte. Geschichte, die irgendwann vielleicht Leben rettet.\n\nGeschichte darüber, was passiert, wenn nicht auf alte, weise Kobolde hören. Wie ich!\n\nGeschichte über Mampf und den Höhleneinsturz...", sourceObjective = "Erlebt Großmutter Krickelkrakels Geschichte noch einmal.", progress = "Unbedingt aufpassen. Noch dabei?", completion = "Ihr nicht zu alt für Respekt vor Ältesten, {name}. Kobold hin oder her.", sourceObjectiveStatus = "unverified-source-field" }
quests[79507] = { id = 79507, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Tag, an dem die Steinköpfe kamen", description = "Was? Wollt gruselige Geschichte?\n\nIhr fragt, Großmutter Krickelkrakel liefert. Aber schön stillsitzen wie gute Weichfüße.\n\nGruseligste Geschichte, die Großmutter kennt, ja. Geschichte über den Tag, als die Steinköpfe kamen...", sourceObjective = "Erlebt Großmutter Krickelkrakels Geschichte noch einmal.", progress = "Hoffentlich Geschichte nicht zu gruselig für Euch.", completion = "<Großmutter Krickelkrakel deutet auf verschiedene Dinge im Raum.>\n\nNicht alle Steinköpfe schlecht, wie scheinen.\n\nAber kleiner Kobold wissen müssen, was passieren. Was passieren können.", sourceObjectiveStatus = "unverified-source-field" }
quests[79508] = { id = 79508, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mipsy Maulwurfreiter", description = "Zeit für fröhliche Geschichte. Nicht alle Tage schlecht.\n\n<Großmutter Krickelkrakel kratzt die Alte Schnarchnase liebevoll hinter den Ohren.>\n\nErzähl Geschichte darüber, wie wir Freunde mit Maulwürfen sein. Geschichte von Mipsy Maulwurfreiter...", sourceObjective = "Erlebt Großmutter Krickelkrakels Geschichte noch einmal.", progress = "Noch da?", completion = "Weichfüße lieben die.\n\nWas von Maulwurf denken? So gut reiten können wie Mipsy?", sourceObjectiveStatus = "unverified-source-field" }
quests[79510] = { id = 79510, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die dochtlose Kerze", description = "Erzähle jetzt Geschichte von sehr weit entferntem Ort namens \"Oberfläche\". Neue Freunde von dort, ja, sie wissen, wovon Großmutter Krickelkrakel reden.\n\n<Großmutter Krickelkrakel nickt weise und deutet zu Euch.>\n\nGeschichte darüber, wie Kobolde vor langer Zeit fanden und was dort fanden. Geschichte von dochtlose Kerze...", sourceObjective = "Erlebt Großmutter Krickelkrakels Geschichte noch einmal.", progress = "Ort bekannt vorkommen?", completion = "Ihr gut im Zuhören, {name}. Großmutter Krickelkrakel Euch zum Ehrenweichfuß ernennen.\n\nVielleicht nächstes Mal Ihr Geschichte für Großmutter Krickelkrakel haben. Nie zu alt für neue Geschichten.", sourceObjectiveStatus = "unverified-source-field" }
quests[79511] = { id = 79511, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Identitätskrise", sourceObjective = "Sprecht mit Glutthal im Siegreichen Antlitz.", completion = "Ich schätze, Chromie hat Euch geschickt?", sourceObjectiveStatus = "unverified-source-field" }
quests[79512] = { id = 79512, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wer seid Ihr?", sourceObjective = "Sprecht mit 9 Besuchern von Valdrakken.", progress = "Habt Ihr Eure Aufklärungsmission abgeschlossen?", completion = "Interessant... Das sind recht unterschiedliche Antworten.", sourceObjectiveStatus = "unverified-source-field" }
quests[79513] = { id = 79513, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abenteuer auf den Dracheninseln: Seid Ihr selbst", description = "Ich sorge mich um Glutthal. Ihre Stimmung hat sich zunehmend verfinstert.\n\nSie mischt sich unter die Bürger der Stadt, um Dinge zu finden, die sie mit ihnen gemein hat, anstatt danach zu suchen, was sie einzigartig macht.\n\nVielleicht wäre eine größere Versuchsgruppe angebracht?\n\nSie braucht Geschichten, die sie leiten. Es gibt viele Personen auf den Dracheninseln, die solche Geschichten zu erzählen haben.\n\nSprecht mit ihnen.\n\nIch würde gerne selbst gehen, aber die Pflichten einer Schuppenkommandantin kennen keine Pause.", sourceObjective = "Sprecht mit 8 Einwohnern der Dracheninseln und hört Euch ihre Geschichten an.", completion = "Vielen Dank, {name}. Wenn das Glutthal nicht hilft, dann weiß ich auch nicht weiter.", sourceObjectiveStatus = "unverified-source-field" }
quests[79514] = { id = 79514, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Droht mir nicht mit Spaß", description = "Glutthal wirkt besorgt, aber ich bin mir sicher, sie wird zurückkommen. Und wenn sie wieder da ist, wird sie sich eine Antlitzgestalt aussuchen!\n\nChromie hat uns alles über die Festlichkeiten erzählt, die Drachen früher für ihren Antlitztag ausgerichtet haben.\n\nAlso werden Kalecgos und ich Sachen in die Luft jagen! Hauptsächlich Feuerwerk.\n\nWir brauchen für die Herstellung aber ein paar arkane Überreste.\n\nZum Glück gibt es gleich vor dem Garten der Einigkeit einige Arkanelementare, die geerntet werden wollen.\n\nWir drei haben alle Hände voll mit anderen Vorbereitungen hier in Valdrakken zu tun.", sourceObjective = "Sammelt 100 arkane Überreste von instabilem Arkana in den Kaskaden.", progress = "Diese instabilen Elementare sind die perfekte Basis für das Feuerwerk!", completion = "Na bitte!", sourceObjectiveStatus = "unverified-source-field" }
quests[79515] = { id = 79515, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sammelt Eure Rosenblüten", description = "Glutthal ist ziemlich gestresst. Das erinnert mich an eine gewisse andere Bronzedrachin, als sie ihr Antlitz gewählt hat.\n\nAber keine Sorge! Sobald Glutthal zurück ist, werden wir ein angemessenes Antlitztagsfest ausrichten.\n\nDas Feuerwerk wird die Farben der Drachenschwärme aufnehmen.\n\nJede Enklave der Stadt pflanzt besondere Blumen an, die dem Schwarm der Enklave entsprechen.\n\nDrei von jeder Farbe sollten für die erste Charge Feuerwerk genügen.", sourceObjective = "Sammelt jeweils 3 Blumen jeder Schwarmfarbe in Valdrakken.", completion = "Danke, {name}. Das sollte reichen.", sourceObjectiveStatus = "unverified-source-field" }
quests[79521] = { id = 79521, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beweisbeschlagnahmung", description = "Ratsvorsteher Merrix hat den Transport von Handelswaren aus den Tiefen über dieses Lager genehmigt. Allerdings haben wir einen Tipp bekommen, dass mehr als nur Handwerksmaterialien hierher geliefert werden sollen.\n\nDornogal sorgt für eine strikte Einhaltung der Regeln darüber, was mit wem gehandelt wird. Jeglicher Handel ist den Edikten unterworfen und nicht den Interessen Einzelner. Wir dulden keinen unerlaubten Handel.\n\nWir haben bereits in ein paar dieser Kisten hineingeschaut, aber noch nichts gefunden. Bitte helft uns bei der Kontrolle.", sourceObjective = "Sammelt 3 beschlagnahmte Lieferungen.", progress = "Der Tipp, den wir erhalten haben, stammte aus einer höchst zuverlässigen Quelle. Da muss etwas dran sein.", completion = "Seltsam... Das sind ganz normale Handelswaren. Hier gibt es nichts Illegales.\n\nIst das alles, was Ihr gefunden habt?", sourceObjectiveStatus = "unverified-source-field" }
quests[79522] = { id = 79522, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zurückgehaltene Informationen", description = "Irgendetwas müssen wir da übersehen. Der Tipp, den wir erhalten haben, stammte aus einer sehr zuverlässigen Quelle. Wir haben keinen Grund zur Annahme, dass wir getäuscht wurden.\n\nDer Ratsvorsteher wird darauf beharren, dass wir der Sache auf den Grund gehen, und ich werde ihn nicht enttäuschen.\n\nWir haben den Arbeitern keine weiteren Informationen entlocken können, aber vielleicht habt Ihr mehr Glück.\n\nSprecht mit denen, die wir hier festgehalten haben, und schaut, ob Ihr etwas in Erfahrung bringen könnt.", sourceObjective = "Befragt 5 Streckenarbeiter, um Informationen über die Lieferungen zu erhalten.", progress = "Irgendjemand hier muss etwas wissen.", completion = "Ah-ha! Doppelte Böden in den Kisten? Sehr clever.\n\nDas allein könnte schon Beweis genug sein, um dieses Lager für immer zu schließen. Aber für die Unterlagen des Ratsvorstehers benötigen wir einen vollständigen Bericht über alle Schmuggelwaren, die wir finden.", sourceObjectiveStatus = "unverified-source-field" }
quests[79523] = { id = 79523, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Etwas Verstecktes", description = "Sie haben also zusätzliche Fächer in die Kisten eingebaut, um weitere Gegenstände zu verstecken, was? Das erklärt, wie sie Waren in und aus Dornogal geschmuggelt haben, ohne dass unsere Auditoren es bemerkten.\n\nGute Arbeit, {name}! Jetzt kommt der unterhaltsame Teil unserer Aufgabe: Die Kisten müssen aufgebrochen und die Schmuggelware als Beweismittel sichergestellt werden.\n\nSchlagt die Kistenböden heraus und bringt alles, was ihr findet, zu mir zurück.", sourceObjective = "Zertrümmert 3 Kisten mit doppeltem Boden, um nach darin versteckten Beweisen zu suchen.", progress = "Ich hoffe, Ihr hattet diesmal mehr Glück.", completion = "<Kragad runzelt die Stirn, als er sich die von Euch gefundenen Waren ansieht.>\n\nEinige dieser Waren stammen aus Azj-Kahet... Es ist uns ausdrücklich untersagt, mit den Nerubern zu handeln. Wir können nicht riskieren, dass unsere Ressourcen in die Hände unserer Feinde fallen.\n\nDer Ratsvorsitzende muss informiert werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[79525] = { id = 79525, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erstattet dem Ratsvorsteher Bericht.", description = "Die Belege, die Ihr gefunden habt... Stahlader ist ein bekannter Schmuggler, den wir schon seit Langem verfolgen. Der Ratsvorsitzende wird sich freuen, endlich handfeste Beweise für seine Aktivitäten und vielleicht sogar seinen Aufenthaltsort zu haben.\n\nBringt diese Belege sofort zu Merrix. Er wird sie eingehend prüfen wollen. Er sagte, er sei auf dem Weg ins Büro, also solltet Ihr ihn auf der Anhöhe des Ratsvorsitzenden finden.\n\nIch werde den Rest der Beweise zusammenpacken und ihm später zukommen lassen. Gute Arbeit heute!", sourceObjective = "Bringt Stahladers Quittungen zu Merrix auf die Anhöhe des Ratsvorstehers in Dornogal.", completion = "<Ihr werdet die Belege wohl auf Merrix Schreibtisch zurücklassen müssen.>", sourceObjectiveStatus = "unverified-source-field" }
quests[79526] = { id = 79526, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufwiegelung", description = "<Auf dem Poster steht:>\n\nMERRIX ist KORRUPT! STAHLADER ist SCHWACH!\n\nSie können die Irdenen nicht beschützen! Die Irdenen sind ihnen egal! Sie verachten die Edikte!\n\nMERRIX wurde BESTOCHEN, damit er Stahladers Schmuggeloperation wiederaufleben lässt! Stahlader VERSTECKT sich hinter MERRIX' Autorität!\n\nSie füllen IHRE Taschen mit dem, was EUCH gehört!\n\nGLAUBT IHNEN KEIN WORT!", sourceObjective = "Sprecht mit Merrix auf der Anhöhe des Ratsvorstehers in Dornogal.\n\nBereitgestellter Gegenstand:", completion = "Ja, ich bin mir der Lage bewusst.\n\nHat mir den ganzen Morgen verdorben.", sourceObjectiveStatus = "unverified-source-field" }
quests[79527] = { id = 79527, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schadensmitigation", description = "Obstorn hat bestätigt, dass der für meine Versorgungslinie von den Tiefen nach Dornogal zuständige Aufseher Ardgrin meinen Friedensbewahrern den Tipp gegeben hat.\n\nDeshalb denke ich, dass Ardgrin auch diese aufrührerischen Poster verfasst hat. Er muss seine Arbeiter mit der Verteilung in der Stadt beauftragt haben.\n\nWir müssen sie unbedingt entfernen, bevor die Gerüchte noch weitere Kreise ziehen. Reißt sie für mich ab.", sourceObjective = "Reißt 8 aufrührerische Poster in Dornogal ab.", progress = "Ich möchte nicht, dass sich die Gerüchte noch weiter verbreiten.", completion = "Sehr gut.\n\nDas wird den Schaden von Ardgrins Rufschädigungsversuchen mir gegenüber etwas einschränken.", sourceObjectiveStatus = "unverified-source-field" }
quests[79528] = { id = 79528, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gerüchte zerstreuen", description = "Es haben bereits viele meiner Friedensbewahrer von Ardgrins Aufwiegelungsversuchen Wind bekommen.\n\nEinige sollen angeblich langsam das Vertrauen in meine Eignung als Ratsvorsteher verlieren, weil sie glauben, ich hätte Bestechungsgelder von Schmugglern angenommen.\n\nIch kann zwar beweisen, dass es keine solche Zahlungen gab, aber wir müssen verhindern, dass sie sich hinter vorgehaltener Hand darüber unterhalten und das Gerücht sich noch weiter verbreitet. Lügen müssen nur oft genug wiederholt werden, bis sie als Wahrheit betrachtet werden.\n\nSolltet Ihr sie dabei erwischen, wie sie darüber reden, geht bitte dazwischen.", sourceObjective = "Verscheucht 6 murmelnde Friedensbewahrer in Dornogal.", completion = "Ich freue mich zu hören, dass die meisten von ihnen vernünftig waren.", sourceObjectiveStatus = "unverified-source-field" }
quests[79529] = { id = 79529, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meine Hand leiten", description = "Ich weiß zwar nicht, ob Ardgrin mich einfach nur sabotieren oder eine direkte Konfrontation herbeiführen wollte, aber die Konfrontation bekommt er auf jeden Fall.\n\nIch glaube zwar, dass die Sache friedlich beigelegt werden kann, aber als Ratsvorsteher sind mir die Hände gebunden. Stahlader ist zwar nie im Stein erschienen, doch nun muss er das.\n\nBitte begleitet mich, wobei ich Euch vorher noch einige Dinge erzählen muss. Helft mir bei den Vorbereitungen, dann weihe ich Euch ein.", sourceObjective = "Helft Merrix, sich als Stahlader zu verkleiden.", completion = "Ich werde die Sache friedlich beilegen.\n\nAber sollte Ardgrin unbedingt auf Gewalt aus sein, werden wir entsprechend reagieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[79530] = { id = 79530, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Übles Geschäft", description = "Seit der Abschaltung der Maschinen war ich nicht mehr in den Tiefen. Obstorn muss uns zu Ardgrins Lager führen.\n\nDort werde ich versuchen, mit ihm zu reden. Sollte das nichts bringen, wovon ich ausgehe, werden wir entsprechend reagieren. Wir wollen ihn wieder in den Schoß der Familie zurückführen, nicht mit Gewalt zur Unterwerfung zwingen. Durch Angst zu herrschen erweckt lediglich Groll.\n\nWir treffen Euch in den Tiefen. Bitte beeilt Euch und behaltet alles für Euch.", sourceObjective = "Trefft Euch in den Schallenden Tiefen an Tor von Heilsturz mit Stahlader und stellt dann Aufseher Ardgrin.", completion = "Nun, da Ardgrin bereit ist zu reden, werden wir reden. Dann wird sich alles klären.\n\nIch bin Euch dankbar, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[79532] = { id = 79532, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tüftler, Schneider, Soldat, Spinne", description = "Danke nochmal, dass Ihr Spindel aus ihrer misslichen Lage gerettet habt, mein Häppchen. Als Belohnung für Eure Arbeit dürft Ihr einen Webrahmen nehmen, um meinen neuesten Wandteppich zu weben.\n\nMeesk die Giftzunge bedroht meine Weberatten. Er beleidigt meine Königin. Und er verleiht Ansureks Desinformationskampagne Glaubwürdigkeit, ohne sich auch nur einen Gedanken über die Konsequenzen zu machen.\n\nIch denke, es ist an der Zeit, dass ich Meesk und seinesgleichen eine Botschaft übermittle. Geht in die Stadt und findet so viel über die \"Giftzunge\" heraus, wie Ihr könnt.", sourceObjective = "Erkundigt Euch bei den Bewohnern des Umbralbasars über Meesk die Giftzunge.", completion = "Hihihi ... Tatsächlich? Es sollte mich nicht überraschen, dass jemand so Geschwätziges wie Meesk eine Vorliebe für die eher banalen Freuden des Untergrunds hat.\n\nEr ist so hochmütig... und unersättlich. Das sollte für unsere Absichten mehr als genug sein, denke ich.", sourceObjectiveStatus = "unverified-source-field" }
quests[79538] = { id = 79538, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gestrüppgestank", description = "Jenni sagt, dass ein paar Krabbler die Goblins angreifen. Ich selbst habe noch keine gesehen, aber ich rieche da eine Gelegenheit!\n\nWir haben unser eigenes krabblerabschreckendes Parfüm. Das ist das gleiche Rezept, das wir auch für das Räucherwerk in der Stadt verwenden. Tragt es auf und schon bleibt Euch alles vom Hals! Ich bin mir sicher, dass wir einiges davon an die Goblins verkaufen können.\n\nEs fehlt mir nur an Materialien... insbesondere an Duftsalbeiästen. Wenn Ihr mir einige davon bringen könntet, beteilige ich Euch am Gewinn!", sourceObjective = "Sammelt Duftsalbeiäste für Rhubarn.", progress = "Wenn Ihr Füße riecht, seid Ihr an der richtigen Stelle.", completion = "Die habe ich direkt gerochen, als Ihr reinkamt! Das sollte passen.", sourceObjectiveStatus = "unverified-source-field" }
quests[79539] = { id = 79539, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elektrifizierend!", description = "Ihr wollt der Venture Company helfen? Und es macht Euch nichts aus, entbehrlich zu sein?\n\nOkay, dann hört zu. Als wir hierhergezogen sind, gab es keine Monster in der Stadt. Aber jetzt finden wir tote Arbeiter, und zwar zerkaut. Das ist schlecht fürs Geschäft.\n\nGlücklicherweise habe ich einen Weg, Geld daraus zu schlagen... einen Elektrifizierungshelm. Ich nenne ihn den Entwanzerhut.\n\nNehmt das aktuellste Modell und führt außerhalb der Stadt ein paar Testläufe durch. Tötet die Käfer. Die Niffen werden Euch und den Entwanzerhut bei der Arbeit sehen. Und schon hagelt es gute Rezensionen.", sourceObjective = "\"Werbt\" für den Entwanzerhut, indem Ihr außerhalb von Mmarl Nothschwärmer damit schockt.", progress = "Er sollte sie einfach umbringen, aber wer weiß das schon? Vielleicht erlebt Ihr ja noch ganz andere Sachen.", completion = "Es gab also zusätzliche Effekte? Super! Der Hype ist also echt! Was für eine Vorführung! Jetzt werden die Bestellungen nur so reinpurzeln!\n\nHabt Ihr mal überlegt, zum wandelnden Werbeschild zu werden? Damit könnte ich zukünftig noch mehr Zaster einnehmen. Hier aber erst mal Euer Lohn.", sourceObjectiveStatus = "unverified-source-field" }
quests[79540] = { id = 79540, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Party ist vorbei", description = "Nein, nein, nein!\n\nIch bin es ja gewohnt, mit diesen ganzen Zusätzen in unserem Wasserloch klarzukommen, nur damit die Werte auf einem \"halbwegs sicheren\" Niveau bleiben, aber Spinnen, die uns zu Tode kauen? Das nehme ich nicht hin.\n\nDas ist UNSER Loch, warum müssen die so lästig sein?", sourceObjective = "Untersucht das Gebiet um das Becken in Mmarl.", completion = "Wir haben dort ein Leuchtfeuer mit Räucherwerk platziert, um die Käfer fernzuhalten. Wenn die Goblins sich daran zu schaffen gemacht haben...", sourceObjectiveStatus = "unverified-source-field" }
quests[79541] = { id = 79541, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Im Feuer verbrennen", description = "Die Goblins haben also das Räucherwerk mitgenommen, das bisher diese lästigen Plagen abgeschreckt hat... weil es schlecht roch?\n\nEhrlich gesagt überrascht mich das nicht. Vielleicht sollten wir ihnen zeigen, dass sie zusammenarbeiten müssen. Geht mit gutem Beispiel voran! Hier, ich leihe Euch meinen Flammenwerfer aus. Der funktioniert ganz sicher, ohne schräge... hühnerartige Effekte.\n\nGeht dort rein, räumt die Nester aus und platziert wieder das richtige Räucherwerk!", sourceObjective = "Verbrennt Stütznest Herz und ersetzt das Räucherwerk in der Höhle bei Mmarl.", progress = "Die Höhle liegt direkt vor uns.", completion = "Okay, dieser Flammenwerfer. Ich brauche ihn. Ich muss wohl mal mit Gazlowe reden... Aber erzählt niemandem davon.", sourceObjectiveStatus = "unverified-source-field" }
quests[79542] = { id = 79542, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Ladung des Ratsvorstehers", description = "Ratsvorsteher Merrix verlangt nach Euch in seinem Büro.\n\nEr hat die Dokumente erhalten, die Ihr zurückgelassen habt, und möchte mit Euch über Stahlader sprechen.\n\n<Saradi sieht Euch unbeeindruckt an. Sie scheint auch keine Irdene der großen Worte zu sein.>", sourceObjective = "Trefft Merrix auf der Anhöhe des Ratsvorstehers in Dornogal.", progress = "Wie schön, dass Ihr es geschafft habt. Die Spannung hat mich aufgefressen.", completion = "Stahlader ist ein Paradoxon in einer Stadt, die auf Recht und Ordnung beruht.\n\nVielleicht bietet sich hier eine Möglichkeit an.", sourceObjectiveStatus = "unverified-source-field" }
quests[79543] = { id = 79543, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dornogals Wohltäter", description = "Ihr seid in einer einzigartigen Position, {name}. In einer Position, in der sich viel in Erfahrung bringen lässt.\n\nIhr habt jene getroffen, die danach trachten, diesen \"Ediktebieger\" vor Gericht zu bringen, aber was ist mit dem Volk von Dornogal? Was halten die Irdenen von diesem Stahlader?\n\nSeid so nett und bringt die Schmuggelware, die Ihr abgefangen habt, zu den vorgesehenen Empfängern. Sagt ihnen, dass sie ein Geschenk eines \"gemeinsamen Freundes\" seien.\n\nIhr werdet überrascht sein, wer von diesen... illegalen Taten profitiert.", sourceObjective = "Verteilt die Schmuggelware in Dornogal.", completion = "Harthan hat also Ardgrin erwähnt?\n\nEr ist ein Handelsaufseher aus den Schallenden Tiefen. Wenn er ein Problem mit Stahlader hat, ist das ein Grund zur Sorge.", sourceObjectiveStatus = "unverified-source-field" }
quests[79544] = { id = 79544, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sicherheit durch Handel", description = "Wenn wir den Streit zwischen Stahlader und Ardgrin auf gütliche Art beilegen wollen, müssen wir ein paar neue Freunde finden.\n\nEiner von Ardgrins Angestellten, Obstorn, ist Stammgast in einer Glutbräu-Spelunke hier in Dornogal, die nur von Maschinenflüsterern betreten werden darf.\n\nSelbst ich als Ratsvorsteher komme dort nicht hinein. Doch es gibt andere in der Stadt, die das können.\n\nDie Händlerin Bevrusi aus Gundargaz sollte Euch einschleusen können. Für einen kleinen Obolus verschafft sie Euch sicher Zugang.", sourceObjective = "Überzeugt Bevrusi, Euch Zugang zu der Glutbräu-Spelunke zu verschaffen.", progress = "Kenne ich Euch?", completion = "Also, was sagt Ihr, Oberflächenläufer?\n\nIhr poliert mir den Rücken, und ich den Euren. Einverstanden?", sourceObjectiveStatus = "unverified-source-field" }
quests[79545] = { id = 79545, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Marktvögtin der Schmiedegründe", description = "Ich habe gehört, dass flüssiger Opal bemerkenswert schmeckt. Aber wie oft ich die Auktionen hier auch durchstöbere, er steht nie zum Verkauf. Er ist ziemlich selten.\n\nZu Eurem Glück gibt es eine Person, die das Zeug auftreiben kann: Vokgret, die Marktvögtin der Schmiedegründe. Ohne ihr Wissen zirkuliert nichts in den Handelsströmen der Stadt.\n\nIch vermeide für gewöhnlich, mit einer so... gut vernetzten Person wie ihr Geschäfte zu machen. Aber Ihr habt da sicher keine Bedenken!\n\nUm diese Zeit findet Ihr sie drüben im Gasthaus.", sourceObjective = "Erwerbt eine Phiole mit flüssigem Opal von Vokgret.", progress = "<Vokgret spricht, ohne von ihren Papieren aufzusehen.>\n\nIn der Stadt ist wirklich ziemlich viel los.", completion = "Alle Ecken und Kanten der Schmiedegründe arbeiten in mechanischer Geschlossenheit wie die Zahnränder einer Maschine.\n\nWenn nur ein Teil versagt, bricht alles zusammen.\n\nDoch trotz der Unterbrechungen habt Ihr Euch bewiesen.\n\nMacht weiter so, dann fällt das bald den richtigen Leuten auf.\n\nWenn es das nicht schon ist.\n\n<Vokgret blickt Euch über ihre Brille hinweg an und lächelt.>", sourceObjectiveStatus = "unverified-source-field" }
quests[79546] = { id = 79546, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Maschinenspelunke", description = "Die Maschinenflüsterer sind seltsame, geheimnisvolle Einheiten, von denen einige zu Paranoia neigen.\n\nNichtsdestotrotz muss der Groll, den sie gegen Stahlader hegen, besänftigt werden.\n\nWie Ihr in den Schmiedegründen gesehen habt, brachte ihr Streit mit einem einzelnen Schmuggler die ganze Stadt in Gefahr. Als Ratsvorsteher werde ich das nicht hinnehmen.\n\nLasst uns mit Obstorn sprechen, einem Angestellten von Ardrin. Vielleicht kann er seinem Aufseher in den Tiefen eine diplomatische Botschaft überbringen.\n\nIch treffe Euch in den Tunneln.", sourceObjective = "Betretet die Spelunke in den Tunneln unterhalb von Dornogal und konfrontiert Obstorn.", progress = "Ich möchte, dass wir Worte austauschen und keine Schläge.", completion = "Ich verabscheue Gewalt, {name}.\n\nUnd Dissens, Verzweiflung und Misstrauen. Das alles sind Folgen, wenn man per Angst regiert.\n\n\n\nAber manchmal bringt Gewalt auch Klarheit - und damit Enthüllungen.", sourceObjectiveStatus = "unverified-source-field" }
quests[79552] = { id = 79552, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heißes Wachs", description = "Oh. Feuerbienen bisschen größer als Janky erwartet. Böse aussehen.\n\nAndere Stöcke aber noch böser. Hier beste Stelle.\n\nIhr Wachs holen. Janky bleiben zum... Überwachen. Ja!", sourceObjective = "Sammelt 12 Stücke Feuerbienenwachs im Aschenholtz.", progress = "Ist Feuerbienenwachs heiß genug, dass selbst schmilzt?", completion = "Ja! Das wird gute Kerze, Janky sicher.", sourceObjectiveStatus = "unverified-source-field" }
quests[79553] = { id = 79553, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Naturheilmittel", description = "Wir haben die meisten der Verletzten stabilisiert. Aber viele der von Euch geretteten Irdenen brauchen mehr Hilfe. Neruber kämpfen oft mit ätzenden Giften, die selbst unsere steinernen Körper angreifen.\n\nDas Fleisch der Fungianer wird seit langer Zeit von unseren Heilern wegen seiner medizinischen Eigenschaften genutzt. Die Übernahme des Steinbruchs durch die Fungianer ist ein unerwarteter Glücksfall, den wir uns zunutze machen werden.\n\n<Adelgonns grimmige Mine strahlt Stolz aus.>\n\nWir werden uns anpassen, wie es die Freien schon immer getan haben.\n\nAber ich kann Ebona nicht alleinlassen. Würdet Ihr mir helfen?", sourceObjective = "Sammelt 10 fungianische Klumpen in der Erzgrube.", progress = "Bitte beeilt Euch. Das Gift der Neruber richtet irreversible Schäden an, wenn man ihm nur genug Zeit dazu gibt. Wenn es ihre Körper zu sehr beschädigt oder in ihren Erinnerungsedelstein eindringt... können wir sie vielleicht nicht mehr retten.", completion = "Ihr habt mehr als erwartet mitgebracht! Danke, ich werde jetzt die Heilpackung herstellen.", sourceObjectiveStatus = "unverified-source-field" }
quests[79554] = { id = 79554, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heilige Kohlenwasserstoffe", description = "Diese Andachtskerzen könnten den Koboldkerzenschmied Janky in Gundargaz interessieren.", sourceObjective = "Sammelt Andachtskerzen für Janky in Gundargaz.", progress = "Wie neue Kerze wohl riechen?", completion = "<Janky knabbert an einer der Kerzen.>\n\nMhmm... mmm... Fischöl und... ein wenig... Sonnenblüte?\n\nInteressante Technik, ja!", sourceObjectiveStatus = "unverified-source-field" }
quests[79555] = { id = 79555, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tiefwaxgalax", description = "Das Beschaffen dieser wachsartigen Substanz mag nicht gerade angenehm sein, doch es scheinen sich fabelhafte Kerzen daraus fertigen zu lassen.\n\nDer Kerzenschmied Janky in Gundargaz hätte bestimmt Interesse daran.", sourceObjective = "Sammelt wachsartige Ausscheidungen und bringt sie zu Janky in Gundargaz.", progress = "Was Ihr Janky bringen?", completion = "Gutes Käferwachs, {name}! Daraus feine Käferkerze machen.\n\nSogar mit Duft!", sourceObjectiveStatus = "unverified-source-field" }
quests[79556] = { id = 79556, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausbildung vor Ort", description = "Steinköpfe betreiben ganzen Ort mit Dampf. Haben Lava und Wasser, ist logisch.\n\nReparaturen nix gut laufen, wir hören. Keine neuen Teile aus Fabrik. Schrott verwenden \"gegen Regeln\", haben gesagt. Oft.\n\nHelfen, alte Maschinen zum Laufen bringen. Wir zusehen und lernen. Vielleicht nicht angeschrien werden für helfen.", sourceObjective = "Helft Dampfwächter Wurft bei der Reparatur der Dampffabrik.", progress = "Wie gehen?", completion = "Sehen aus wie Kinderspiel. Dampf in Rohr leiten, möglichst nicht selbst verbrühen.\n\nIch verstehen!", sourceObjectiveStatus = "unverified-source-field" }
quests[79558] = { id = 79558, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gefiederter Feind", description = "Das Schmuckstück scheint eine Art Nobelgartendekoration zu sein. Es sollte vermutlich zum Fest in Klingenhügel zurückgebracht werden.", sourceObjective = "Bringt den Nobelgartenschmuck zu Sylnaria Seherflamme in Klingenhügel.", completion = "Sieh an, wie ist das denn verschwunden? Keine Sorge, ich kümmere mich darum, dass alle gestohlenen Dekorationen wiederhergestellt werden!", sourceObjectiveStatus = "unverified-source-field" }
quests[79559] = { id = 79559, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Grünschmierritter", description = "Haltet Euch für tapfer?\n\nSuche nach tapfer, aber nicht viel finden. Nicht sicher, ob Ihr zählen. Ihr wie Weichfuß aussehen, der zu Omi rennen, wenn Knie aufgeschürft.\n\nIhr Euch wollen beweisen? Ganz einfach. Mich schlagen so fest Ihr könnt. Versuchen, mich zu töten.\n\nWenn ich nicht tot, ich Euch später töten.\n\nNicht glauben, Ihr mehr als einen Schlag aushalten.\n\nAbgemacht?", sourceObjective = "Tötet den Grünschmierritter.", progress = "Ihr davonrennen?", completion = "Hmm, klingen, als ob hättet härter schlagen sollen. Immer erzählen, dass Ritter nicht tapfer genug.", sourceObjectiveStatus = "unverified-source-field" }
quests[79561] = { id = 79561, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Herr der Riesen", description = "Ich sehen, Ihr Euch mit Quests auskennen. Ihr sicher viele Bestien erlegt, wie sich für gute Ritter gehören.\n\nVersteck von Schmierbaddaden, Riesenschleimkönig, in der Nähe. Perfekte Gelegenheit, um Hof Tapferkeit zu beweisen!\n\nHat riesige Gabel in Kopf stecken, nicht zu verfehlen. Ihr wissen, was zu tun.", sourceObjective = "Tötet Schmierbaddaden, den Riesenschleimkönig.", completion = "Siegreich zurückgekehrt! Tapferkeit an Euch kleben wie Geruch von altem Fett.\n\n<Gehweinen hält inne und schnüffelt leicht.>\n\nWirklich viel Tapferkeit!", sourceObjectiveStatus = "unverified-source-field" }
quests[79563] = { id = 79563, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dame des Sees", description = "Viel Tapferkeit bewiesen. Und Demut. Und Ehre.\n\nEuch gut bei Ritter der Wunden Tafel machen würden.\n\nNur noch eine Aufgabe übrig. Heiligste von allen. Dame des Sees um Segen bitten. Sie entscheiden, ob würdig oder nicht.\n\nSee hinten in Höhle. Eher Teich, aber nicht sagen. Dame des Teichs nicht gut klingen.", sourceObjective = "Erhaltet den Segen der Dame des Sees.", progress = "Nicht weit, direkt hinten in Höhle.", completion = "Nur beste Ritter mit Segen der Dame zurückkehren.\n\nMeisten Ritter irgendwie verloren gehen. Nicht weit eigentlich, sehr merkwürdig.\n\nSo oder so, Ihr guten Ritter abgeben, {name}. Wir sicher.", sourceObjectiveStatus = "unverified-source-field" }
quests[79564] = { id = 79564, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Grünschmierritter kehrt zurück", description = "Zurück sein, wie versprochen.\n\nGehört, Ihr jetzt <tapferer Ritter/tapfere Ritterin>.\n\nBereit, Euren Teil der Abmachung einhalten? Ich EUCH niederschlagen.\n\nIhr hinknien.", sourceObjective = "Kniet vor dem Grünschmierritter und akzeptiert seine Vergeltung.", progress = "Wahl treffen.", completion = "Ihr heute große Tapferkeit bewiesen. Ihr stolz sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[79565] = { id = 79565, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jankys Kerzen", description = "Wo neue Kerze fast fertig, jetzt wir müssen nur Verkaufsstand aufbauen! Dann verkaufen hochwertige Kerzen zu gutem Preis an Leute! Janky garantiert!\n\nEinziges Problem: Wir nix haben Stand. Ihr für mich sprechen mit Bosh in Gun-dar-ghaz, ja? Er alles Nötige haben.\n\nVielleicht müssen handeln, aber Ihr gut reden! Ihr ihn bequatschen für Teile.\n\nWir uns dann da treffen!", sourceObjective = "Beschafft die Teile, die Janky benötigt, um seinen Verkaufsstand in Gundargaz aufzubauen.", progress = "Ihr die Teile haben?", completion = "Gut sprechen, {name}. Ihr eines Tages gut verkaufen.\n\nWie Janky!", sourceObjectiveStatus = "unverified-source-field" }
quests[79574] = { id = 79574, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die zweite Front", description = "Unsere Verstärkung ist schon unterwegs.\n\nDiese Spinnen haben gerade entschieden, wo unsere nächste Mauer stehen wird. Schafft eine Landezone für Generalin Stahlstoß.", sourceObjective = "Markiert die Landezone mit einem Signal.", completion = "Ich werde NICHT riskieren, dass uns die Neruber wieder in die Flanke fallen. Ihr Hinterhalt ist jetzt unser Kampfschauplatz!", sourceObjectiveStatus = "unverified-source-field" }
quests[79575] = { id = 79575, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ente gut, alles gut!", description = "Ich kann unter diesen Bedingungen nicht arbeiten! Irgendetwas hat diese Enten in Aufruhr versetzt. Sie haben fast mein wertvolles goldenes Ei umgeworfen!\n\nWir müssen uns um dieses chaotische Federvieh kümmern! Ich kann sie davon abhalten, das Gasthaus zu betreten, aber könntet Ihr Euch um den Rest kümmern?", sourceObjective = "Verschreckt 10 Enten mithilfe des Horns des Hupens.", progress = "Husch! Husch! ...Habt Ihr sie schon alle verscheucht?", completion = "Endlich, ein Moment des Friedens! Ich danke Euch, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[79576] = { id = 79576, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Quak-salberei", description = "Mein Ei! Mein wertvolles Ei! Während ich ein paar der Nachzügler vom Gasthaus abhielt, tauchte ein ganzer Schwarm auf und hat sich mit einem Teil unserer Deko und einigen Eiern davongemacht. Mein wunderschönes goldenes Erbstück war unter den gestohlenen Stücken!\n\nGenug ist genug. Wir müssen die Invasion dieser Enten beenden.\n\nBitte, {name}. Dieses diebische Federvieh muss aufgehalten werden! Glücklicherweise kenne ich eine Magierin in Orgrimmar, die eine Lösung kennen dürfte.", sourceObjective = "Sprecht mit Tethris Taublicker in der Pfadfinderhöhle in Orgrimmar.", progress = "Habt Ihr schon mit Tethris gesprochen?", completion = "Keine Sorge, ich bin mir sicher, dass er eine gute Lösung finden wird. Wartet hier, ich glaube, ich sehe, wie sich ein Portal bildet.", sourceObjectiveStatus = "unverified-source-field" }
quests[79577] = { id = 79577, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ent-deckungen", description = "Nehmt diesen Trank, {name}. Sobald Ihr ihn trinkt, solltet Ihr in der Lage sein, mit diesem Federvieh zu plaudern.\n\nAch, und wenn Ihr irgendwelche... unerwünschten Nebenwirkungen erlebt, macht mir keine Vorwürfe.", sourceObjective = "Nutzt den Trank, um Informationen aus 5 Enten herauszuholen.", completion = "Was? Einige dieser Enten sind Druiden?\n\nDamit kommen sie uns nicht davon!", sourceObjectiveStatus = "unverified-source-field" }
quests[79578] = { id = 79578, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wo Enten hausen", description = "Wir müssen einfach herausfinden, wo diese Enten unsere gestohlenen Waren verstecken... und mein kostbares Ei! Ach, und natürlich, wer dieser geheimnisvolle Daetan ist.\n\nIch habe Tethris überredet, mir mehr von dem Trank zu überlassen. Nehmt ihn und bringt mir mein wertvolles Erbstück wieder!", sourceObjective = "Findet das Versteck der Enten.", progress = "Wo würde ich mich verstecken, wenn ich eine Ente wäre...", completion = "<Sylnaria begutachtet das goldene Ei sorgfältig.>\n\nHerrje! Hat eine Ente daran geknabbert? Mein armer Schatz, mach dir keine Sorgen... Wir polieren dich bald, bis du wieder glänzt und strahlst!\n\nVielen Dank für Eure Hilfe, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[79579] = { id = 79579, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lufthoheit mit guter Mine zum bösen Spiel", description = "Unser Vorteil ist unsere Luftüberlegenheit. Sie wird aber von den Nerubern und ihren Minen bedroht.\n\nIhr seid mit Eurem Reittier einfach beweglicher als wir mit unseren Booten. Ab in die Luft mit Euch und schaltet diesen Minen aus.\n\nIch werde Euch mit allen Mitteln versorgen, die ich aufbringen kann, damit Ihre Eure Fähigkeiten verbessern könnt.", sourceObjective = "Fliegt durch 5 Neruberminen, während Ihr unter dem Effekt von 'Heilige Lanze' steht.", progress = "Unsere Priester sind vom Licht erfüllt, aber in der Luft sind sie Euch und Euren Ressourcen unterlegen.", completion = "Gut gemacht. Genau die richtige Waffe für die richtige Front.", sourceObjectiveStatus = "unverified-source-field" }
quests[79580] = { id = 79580, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Offensivkonter", description = "Ich werde diesen Bereich nicht aufgeben.\n\nGeht dort raus und tötet alles, was mehr als zwei Beine hat!", sourceObjective = "Tötet 12 Neruber.", completion = "Gut gemacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[79625] = { id = 79625, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nicht ganz tot", description = "Ich bin General Anub'azal.\n\nIch mag es überhaupt nicht, kleine Zweibeiner wie Euch in der Belagerungsfeste zu haben. Aber ich habe das nicht mehr zu entscheiden. Zev'kall drängt mich aus meiner militärischen Festung und versammelt Überkrabbler hinter sich! Die Königin hat ihn zum Hochgeneral ernannt, aber er ist unnatürlich, verzerrt und ungeeignet. Wir dürfen das nicht zulassen!\n\nIch habe entschieden, Euch und Eure Art gegen Zev'kall einzusetzen. Und ja, auch Ihr werdet etwas davon haben.\n\nGrabt Euch mal durch den Haufen da. Ihr werdet schon sehen.", sourceObjective = "Durchsucht den Beutehaufen in der Belagerungsfeste.", progress = "Nur zu, durchsucht den Haufen Unrat.", completion = "Ich habe Pläne für Euch beide.", sourceObjectiveStatus = "unverified-source-field" }
quests[79627] = { id = 79627, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf Wein und Verderb", description = "Ich kann es nun sehen, Häppchen. Ich sehe das Muster unseres jüngsten Geflechts direkt vor meinem inneren Auge.\n\nMeesk wird gut bewacht. Er wiegt sich in Sicherheit. Das ist seine Schwäche.\n\nBegebt Euch zur Stadt. Besorgt eine Flasche seines Lieblingsgetränks und überreicht sie ihm als Geschenk Eures Wohltäters. Sobald Ihr ihn mit Eurem Charme um den Finger gewickelt habt, bringt ihn in die Hochhöhlen, damit er seine wohlverdiente Belohnung erhalten kann.\n\nIch vertraue Euch, {name}. Wenn Ihr unsere Fäden richtig spinnt, garantiere ich Euch ein unterhaltsames Schauspiel.", sourceObjective = "Findet einen Weg, um Meesk die Giftzunge um den Finger zu wickeln.", completion = "Ich habe von Euch gehört, Überkrabbler... davon, wie Ihr durch unsere Stadt huscht und allerlei Ärger anrichtet.\n\nIch bin froh, dass Eure Vorgesetzten endlich den Wert eines Verbündeten wie mir an einem Ort wie diesem erkannt haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[79628] = { id = 79628, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abgesandter des Rates" }
quests[79630] = { id = 79630, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Netzsuche", description = "Oh, den Höhlen sei Dank! Ihr seht so aus, als könntet Ihr helfen.\n\n<Die Neruberin wischt sich die vielen Augen mit einem seidenen Taschentuch ab.>\n\nEs ist einfach schrecklich! Absolut schrecklich! Eine Tragödie! Mein Gatte ist verschwunden! Wir haben gestern erst geheiratet! Wir hatten so eine schöne Trauung...\n\nAber als wir uns am Abend zurückziehen wollten, verschwand er.\n\n<Sie schnieft laut.>\n\nIch flehe Euch an, könnt Ihr nach ihm suchen und ihn mir zurückbringen?", sourceObjective = "Findet Arax'nes Ehemann, Klaskin, im Umbralbasar.", completion = "Bitte helft mir, nach Hause zu kommen!", sourceObjectiveStatus = "unverified-source-field" }
quests[79631] = { id = 79631, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Klaskins große Flucht", description = "Seidenfäden, ich bin gerettet!\n\nEs ist unglaublich wichtig, dass ich es nach Hause schaffe, ohne dass meine Frau mich sieht.\n\nIch bin gestern Abend nach unserer Hochzeit abgehauen, und wenn sie mich sieht, wird sie mich umbringen! Wenn die Wachen mich erwischen, werden sie mit Sicherheit Arax'ne alarmieren.\n\nHelft Ihr mir, die Wachen zu umgehen und nach Hause zu kommen?", sourceObjective = "Bringt Klaskin zu Arax'ne auf dem Umbralbasar zurück.", progress = "Bitte beeilt Euch!", completion = "Wunderbar! Klaskin, du bist so süß.", sourceObjectiveStatus = "unverified-source-field" }
quests[79633] = { id = 79633, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Vermächtnis der Weberin", description = "Ach, das ist so aufregend! Ich warte schon lange darauf, jemanden zu treffen, der selbst Überkrabbler herumkommandiert.\n\nOh, ich werde doch aber nicht allzu weit gehen müssen, oder? Ich soll heute Abend die aufstrebende Prominenz der Sureki bewirten.", sourceObjective = "Bringt Meesk die Giftzunge zur Weberin.", completion = "Täuscht Euch nicht, {name}. Meesks willkürliche Neigungen interessieren mich nicht. Sie waren ganz praktisch, um ihn zu vernichten, aber es steht mir nicht zu, mich über zweifelhafte Moralvorstellungen abfällig zu äußern.\n\nWir alle tappen im Dunkeln auf unserer Suche nach Dingen, die uns Zufriedenheit schenken. Meesk hat selbst entschieden, Neferess' Namen zu seinem eigenen Vorteil zu nutzen. Und er hat eine meiner Weberatten in Gefahr gebracht. Er hat sich sein Leiden selbst zuzuschreiben.", sourceObjectiveStatus = "unverified-source-field" }
quests[79634] = { id = 79634, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "NICHT BENUTZEN - Angesehen beim Konvent der Tiefen" }
quests[79636] = { id = 79636, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abgesandter der Versammlung" }
quests[79641] = { id = 79641, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wer zuletzt lacht", description = "Die Kobyss werden übermütig, wenn sie das Gefühl haben, dass sie unsere Ehrengründe entweihen können. Ich denke, wir sollten ihre Zähne einsammeln, um das Grinsen aus ihren Gesichtern zu wischen.\n\nKommt! Mein Bruder und ich werden unser Land von diesem Schmutz säubern! Versucht Schritt zu halten!", sourceObjective = "Sammelt Kobysszähne von getöteten Kobyss.", progress = "Jetzt will ich sie mal grinsen sehen!", completion = "Sehr gute Arbeit, würde ich sagen.\n\nUnd Ihr konntet sogar mithalten!", sourceObjectiveStatus = "unverified-source-field" }
quests[79642] = { id = 79642, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Stab über die Kobyss brechen", description = "Ohne ihre magischen Waffen werden die Zauberwirker der Kobyss nicht in der Lage sein, ihre verdorbene Totenbeschwörungsmagie einzusetzen.\n\nStehlt ihre Stäbe, damit wir sie in die Heilige Flamme werfen und vernichten können.", sourceObjective = "Sammelt 5 Dunkelwasserstäbe.", progress = "Habt Ihr Dunkelwasserstäbe gefunden?", completion = "Gute Arbeit!", sourceObjectiveStatus = "unverified-source-field" }
quests[79643] = { id = 79643, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schreckenszahn, der Schreckliche", description = "Mein Bruder und ich haben den Kobyss ordentlich zugesetzt, {name}, aber Ihr hättet mehr tun können. \n\nDer abscheulichste Kobyss von allen wartet noch immer auf meine Klinge. Wenn wir ihren Anführer ausschalten, wird der Rest sich in das Wasser zurückziehen, aus dem sie gekommen sind.\n\nHolen wir uns den Kopf von Schreckenszahn!", sourceObjective = "Tötet Schreckenszahn den Gnadenlosen.", progress = "Bereit, ein paar Kobyss zu töten?", completion = "Nein, bitte! Steht auf! ... Theleon...", sourceObjectiveStatus = "unverified-source-field" }
quests[79644] = { id = 79644, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geht zum Priorat", description = "Ich... Ich weiß nicht, was ich sagen soll. Theleon...\n\nIch werde s-seinen Leichnam nehmen. Am Priorat werden sie wissen, was zu tun ist.\n\nMein geliebter Bruder... Es sollte doch nicht so enden...", sourceObjective = "Trefft Schwester Etna Feuersbrynst im Priorat der Heiligen Flamme.", completion = "So jung wurde er uns geraubt. So mutig und kühn. Vielleicht zu kühn.", sourceObjectiveStatus = "unverified-source-field" }
quests[79645] = { id = 79645, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Süßstich-Befall", description = "Der arme Theleon. Ich gab ihm damals seine ersten Lehrstunden im Kampftraining. Ich werde ihn auf dem Weg zu seinem letzten Scheiterhaufen begleiten.\n\nAber zuerst habe ich noch ein Anliegen an Euch.\n\nIch habe versucht, einen Befall von Süßstichen zu bekämpfen, die unsere Weinherstellung bedrohen. Jetzt muss jemand anders sie erledigen, während ich mich um Theleons Leichnam kümmere.\n\nSeid schnell und clever und bringt mir etwas von ihrem Toxin, während Ihr sie bekämpft. Daraus können wir ein Gift für ihre Brutstätten herstellen, damit wir die Plage ein für allemal los werden.", sourceObjective = "Sammelt 10 Phiolen Wespengift.", progress = "Habt Ihr diese Dinger getötet?", completion = "Gute Arbeit! Ihr habt ja kaum Stiche abbekommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[79646] = { id = 79646, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gedenkwein", description = "Ach, Theleon. Er ist seinem großen Bruder überall hin gefolgt.\n\nWährend wir Theleon für seine letzte Ruhestätte vorbereiten, würdet Ihr Bruder Abealard mit einer Fuhre Gedenkwein für die Trauermesse aushelfen?", sourceObjective = "Stellt mit Bruder Abealard Gedenkwein her.", progress = "Habt Ihr Bruder Abealard geholfen?", completion = "Eine Schande, dass wir so viel von diesem Wein herstellen müssen.", sourceObjectiveStatus = "unverified-source-field" }
quests[79647] = { id = 79647, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lodernde Erinnerungen", description = "Sybaestan könnte jetzt Eure Unterstützung brauchen. Sein kleiner Bruder war zugleich sein bester Freund. Die beiden waren unzertrennlich... bis zum Tod. Er leidet sehr.\n\nEs ist Sitte, schriftliche Erinnerungen an unsere Verstorbenen zu verbrennen. Indem wir sie den Flammen übergeben, lassen wir den Schmerz los, damit die Wärme der Erinnerungen uns heilt. Es ist eine bittersüße Zeit. Ihr wart auch an Theleons Seite, als er von uns ging. Das könnte Sybaestan Trost spenden.", sourceObjective = "Helft Sybaestan, um seinen Bruder zu trauern.", progress = "Das Ritual hilft, den Schmerz von vielen zu lindern.", completion = "Es macht mir Sorgen, dass Sybaestan statt Trauer vor allem Zorn im Herzen spürt.", sourceObjectiveStatus = "unverified-source-field" }
quests[79648] = { id = 79648, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Doch irgendjemand fehlt", description = "Theleon war eine gute Seele, aber jetzt müssen wir seine Überreste den Flammen überlassen.\n\nSybaestan ist in keiner Verfassung, seinen Bruder zu tragen. Würdet Ihr seine Überreste holen? Sie liegen bei den anderen, die auf ihre letzte Ruhestätte warten.", sourceObjective = "Holt Theleons sterbliche Überreste.", progress = "Ihr seid stark und habt die nötige Distanz, die Sybaestan gerade fehlt.", completion = "Verschwunden? Alle Leichen sind weg?!", sourceObjectiveStatus = "unverified-source-field" }
quests[79649] = { id = 79649, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Inquisition der Heiligen Flamme", description = "Die Toten sind alle nicht mehr da? Wie kann das sein? Wir haben sie zur Vorbereitung auf ihre Verbrennung aufgebahrt. Wer hätte einen Grund, sie fortzuschaffen? Irgendjemand muss etwas gesehen haben.\n\nBitte hört Euch bei allen in der Umgebung um, ob sie etwas mitbekommen haben. Ich spreche derweil mit unseren oberen Klerikern. Wir werden der Sache auf den Grund gehen und unsere Toten wiederfinden, damit wir sie angemessen verabschieden können.", sourceObjective = "Hört Euch bei den Klerikern vor Ort um.", completion = "Sie haben Euch angegriffen? Und angeblich ist die Priorin daran beteiligt? Das verheißt nichts Gutes.", sourceObjectiveStatus = "unverified-source-field" }
quests[79650] = { id = 79650, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Priorat der Heiligen Flamme: Die Trauer eines Bruders", description = "Ich befürchte, dass die Priorin hinter unseren vermissten Toten stecken könnte-- und hinter unserem vermissten Baron. Sybaestan ist ebenfalls verschwunden, und ich glaube nicht an Zufälle. \n\nSie und Sybaestan haben unsere kürzlichen Verluste schwer mitgenommen. Ich fürchte mich davor, was ihre überwältigende Trauer mit ihren Seelen anstellen kann. Wir müssen sie konfrontieren und wieder zur Vernunft bringen... wenn das möglich ist.\n\nErzählt Generalin Stahlstoß, was Ihr erfahren habt. Wir könnten ihre Unterstützung benötigen. Ich werde hier auf Euch warten.", sourceObjective = "Konfrontiert Priorin Haelsey Murrbet im Priorat der Heiligen Flamme.", progress = "Wir müssen die Priorin konfrontieren.", completion = "Ich wünschte, es wäre anders gekommen... aber wenigstens können sie jetzt Frieden finden.", sourceObjectiveStatus = "unverified-source-field" }
quests[79651] = { id = 79651, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Handelspartner", description = "Wart Ihr bereits in Mmarl? Das ist eine Handelsstadt südöstlich von hier. \n\nWenn Ihr dort seid, müsst Ihr unbedingt von Corbys Grillkünsten probieren!", sourceObjective = "Besucht Mmarl.", completion = "Hallo, {name}! Danke, dass Ihr gekommen seid.", sourceObjectiveStatus = "unverified-source-field" }
quests[79655] = { id = 79655, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arathi von Heilsturz" }
quests[79659] = { id = 79659, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Durchtrennten Fäden" }
quests[79667] = { id = 79667, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das ist elementar" }
quests[79669] = { id = 79669, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ich nehmen Kerze!" }
quests[79679] = { id = 79679, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verwirrt in der Mine", description = "Die Arbeiter sagten, sie hätten Munderut am Ende des Grubengebiets gesehen. Bitte findet ihn und sagt ihm, dass er sich bei mir melden soll.\n\nVielleicht weiß er nicht mehr, wer ich bin, oder dass wir Partner sind. Sagt ihm, er soll an seiner Brust hinab auf das Medaillon schauen, das er trägt. In letzter Zeit verblasst manchmal seine Erinnerung an unsere gemeinsame Zeit, doch das Medaillon ist dazu da, auf ewig unsere Geschichte zu erzählen und unseren Bund darzustellen.", sourceObjective = "Sucht Munderut in der Nibelgazmine.", completion = "Wer seid Ihr? Was macht Ihr hier?\n\nIch meine: Was mache ich eigentlich hier? Wahrscheinlich sammele ich Stacheln. Ich habe mich von den ganzen Elementaren ablenken lassen. Die haben diesen Bereich ganz schön gefährlich gemacht. Ich bin eher Künstler als Kämpfer.", sourceObjectiveStatus = "unverified-source-field" }
quests[79680] = { id = 79680, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rohrflicken", description = "Erdbeben setzen alten Rohren zu. Viele danach undicht und Dampf verlieren. Besonders die, an die man nicht herankommt.\n\n<Draufseherin Rußi deutet auf die Rohre, die sich von Gundargaz bis zur Oberfläche erstrecken.>\n\nSteinköpfe nix haben \"genehmigte Ersatzteile\", aber wir nix können warten.\n\nIhr Leim nehmen und Lecks versiegeln mit dem Klatsch-Platsch-Zeug. Ist aus den besten Käfern, ich selbst gekocht! Wird für heute reichen.", sourceObjective = "Fliegt neben die Lecks in den Dampfrohren über Gundargaz und versiegelt sie mit dem Leim, den Euch der Kobold gegeben hat.", progress = "Nicht selbst an Rohr kleben, ja?", completion = "Seht Ihr? Warten nicht gut. Taten gut.\n\nIhr versteht.", sourceObjectiveStatus = "unverified-source-field" }
quests[79681] = { id = 79681, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Klempnerkräfte", description = "Nicht alle lecken Rohre von außen zugänglich. Manche in Tunneln unter ganz Gundargaz verlaufen.\n\nTunnel zu klein für Steinköpfe, aber Kobolde lieben Tunnel! Nur jemanden brauchen für zeigen Verlauf. Jemand Ihr sein.\n\nBei Problemen Ihr ansprechen Schichtleiter. Er Euch Karten erklären.", sourceObjective = "Nutzt den Tunnelzugang, um den Verlauf der Dampfrohre durch Gundargaz aufzuzeichnen.", progress = "Verlaufen?", completion = "Arbeit gut. Jetzt nächste.", sourceObjectiveStatus = "unverified-source-field" }
quests[79682] = { id = 79682, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Druck kritisch!", description = "Druck noch zu hoch! Irgendwas falsch, nicht nur alte Rohre.\n\nIhr Hauptablassventil öffnen, bevor etwas platzen. Keine Zeit für Handbuchlesen.\n\nUm Folgen später kümmern!", sourceObjective = "Öffnet das Hauptablassventil und kümmert Euch um etwaige Folgen.", progress = "Problem gefunden?", completion = "Immer gut machen, {name}. Vielleicht alte Rohre sich jetzt benehmen?", sourceObjectiveStatus = "unverified-source-field" }
quests[79683] = { id = 79683, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zuhause ist, wo die Kerze ist", description = "Aufregend, ein neues Zuhause zu haben, {name}.\n\nNoch nicht ganz eingelebt. Wir kennen Gundargaz nicht. Gundargaz kennt uns nicht.\n\nZeit, beides in Ordnung zu bringen! Findet heraus, wie hier helfen. Bringt neuen Freunden etwas über uns bei. Kobolde sind klug und freundlich, sollte leicht sein!\n\nFür Anfang, helfen drei Kobolden.\n\nDraufseherin Rußi will sofort an die Arbeit. Denkt sehr an Aufgaben.\n\nGroßmutter Krickelkrakel erzählt viel über Koboldkultur.\n\nUnd Janky will ein neues Geschäft in der Stadt aufmachen und Kerzen an Gundargaz verkaufen.", sourceObjective = "Helft Draufseherin Rußi, Janky und Großmutter Krickelkrakel.", completion = "Danke, {name}. Wegen Euch jetzt neue Heimat haben. Eine Zukunft.", sourceObjectiveStatus = "unverified-source-field" }
quests[79686] = { id = 79686, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Betreff: Fungianer", description = "<Das zerknitterte und abgenutzte Pergament, das wie vergessen im schummrigen Kerzenlicht der Kammer liegt, trägt Spuren von hastig hingekritzelten Forschungsnotizen.>\n\nLogbucheintrag: 235-18-7\nDatum: Fabrikations-Quartalszyklus\n\nBeobachtung: Die Fungianer zeigen ein beschleunigtes Wachstum und verstärkte territoriale Aggression. Die Sporenausbreitung scheint sich im Vergleich zu früheren Aufzeichnungen vervierfacht zu haben.", sourceObjective = "Sammelt die verbleibenden wissenschaftlichen Notizen ein und bringt sie zu ihrem Besitzer in Freyholtz.", progress = "Habt Ihr was Interessantes gefunden?", completion = "Meine Notizen! Ich hatte schon befürchtet, dass meine Forschung für immer verloren wäre!", sourceObjectiveStatus = "unverified-source-field" }
quests[79691] = { id = 79691, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Monster in der Dunkelheit", description = "Aus dem hiesigen Steinbruch haben wir uns stets Lehm und Erz besorgt, bis ihn die Fungianer vor einiger Zeit besetzten.\n\nWir hatten nicht nur Angst davor, dass die Fungianer sich langsam unserem Dorf näherten, sondern...\n\nNachts wurde mehrfach eine Kreatur gesichtet, die viel größer war als die Vertreter unserer Fauna.\n\nZusammen mit dem Verschwinden der Dorfbewohnerin Modhina ist das sicher kein Zufall. Sie hatte vor Kurzem den Steinbruch aufgesucht und ist nicht zurückgekehrt.\n\nWenn Ihr die Tunnel durchsuchen könntet, wären wir Euch sehr verbunden.", sourceObjective = "Erschlagt den Aschesteinpirscher in Edelsteinadertunneln.", completion = "Ein Aschesteinpirscher? Hier? Sein Lebensraum liegt weit unter der Inseloberfläche. Wahrscheinlich haben ihn all die jüngsten Veränderungen gestört.\n\nTrotzdem danke, dass Ihr ihn erledigt habt. Diese Tiere haben ein ausgeprägtes Revierdenken und töten zum Spaß.\n\nUnd was die Tunnel angeht: Dieser Bereich ist wohl nicht mehr zu retten. Die Natur soll ihn sich zurückholen.", sourceObjectiveStatus = "unverified-source-field" }
quests[79692] = { id = 79692, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Begraben, aber nicht vergessen", description = "Vor mehreren Sonnen wagte sich meine Freundin Modhina in die Steinbruchhöhle vor. Sie wollte dort seltenes Erz für Hreka finden, um ihr handwerkliches Können zu verbessern. Ich weiß noch, wie aufgeregt Modhina war. Ein seltenes Gefühl bei Irdenen.\n\nZurückgekehrt ist sie nicht. Die Fungianer hindern uns am Absuchen der Gegend.\n\nEs würde uns sehr viel bedeuten, wenn Ihr sie suchen würdet. Ich hätte nie gedacht, dass man den ganzen Tag daran denken kann, was wäre, wenn...", sourceObjective = "Findet Modhina und ihre Habseligkeiten in Edelsteinadertunneln.", completion = "Ihr seid zurückgekehrt! Habt Ihr Modhina gefunden...? Was ist das alles, was Ihr da tragt?", sourceObjectiveStatus = "unverified-source-field" }
quests[79693] = { id = 79693, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spielt Hearthstone!", description = "Zeit für eine Runde Hearthstone!\n\nHier ist ein Starterpaket. Macht es auf und erweitert Eure Sammlung um diese Karten. Wenn Ihr dann einen Platz am Spieltisch findet, könnt Ihr Euch zu jemandem setzen und spielen!\n\nWenn Ihr keinen Platz findet, möchtet Ihr vielleicht einige wilde Karten... Hier schleicht irgendwo ein zwielichtiger Kartenhändler herum, aber das wisst Ihr nicht von mir...", sourceObjective = "Spielt 5 Hearthstone-Karten an einem Hearthstone-Spieltisch aus oder wilde Karten IN DER NÄHE eines Hearthstone-Spieltisches.", progress = "Gefällt Euch das Spiel bisher? Wagt einen Versuch und spielt diese Karten!", completion = "Wie ist es Euch ergangen? Ihr hatte sicher jede Menge Spaß, ohne zu schummeln!", sourceObjectiveStatus = "unverified-source-field" }
quests[79694] = { id = 79694, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spielt Hearthstone!", description = "Zeit für eine Runde Hearthstone!\n\nHier ist ein Starterpaket. Macht es auf und erweitert Eure Sammlung um diese Karten. Wenn Ihr dann einen Platz am Spieltisch findet, könnt Ihr Euch zu jemandem setzen und spielen!\n\nWenn Ihr keinen Platz findet, möchtet Ihr vielleicht einige wilde Karten... Hier schleicht irgendwo ein zwielichtiger Kartenhändler herum, aber das wisst Ihr nicht von mir...", sourceObjective = "Spielt 5 Hearthstone-Karten an einem Hearthstone-Spieltisch aus oder wilde Karten IN DER NÄHE eines Hearthstone-Spieltisches.", progress = "Gefällt Euch das Spiel bisher? Wagt einen Versuch und spielt diese Karten!", completion = "Wie ist es Euch ergangen? Ihr hatte sicher jede Menge Spaß, ohne zu schummeln!", sourceObjectiveStatus = "unverified-source-field" }
quests[79701] = { id = 79701, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Kavallerie ist da", description = "<Baelgrim bebt vor Zorn.>\n\nDiese verfluchten Neruber. Sie greifen eine Triagestation an! So viele sind verwundet und wehrlos... und doch scheint Ihr Fremdlinge Euch gut zur Wehr zu setzen!\n\nLasst uns jeden einzelnen dieser Käfer in den Boden stampfen.", sourceObjective = "Wehrt den nerubischen Angriff auf das Proszenium ab.", completion = "<Baelgrim ist von Kopf bis Fuß vom Blut und Sekret der Neruber bedeckt.>\n\nGute Arbeit, {name}. Gute, blutige Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[79703] = { id = 79703, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hoffnung, eine Anomalie", description = "<Hreka sieht sich die von Euch beschafften Sachen eine nach der anderen an.>\n\nIhr habt Euer Leben riskiert, um unsere Freundin zu finden.\n\nModhina ist also tot. Ihre Notizen handeln von dem seltenen Erz aus der Höhle, das geschmolzen als wunderschöne Glasur für Tonwaren dient.\n\nWas kann ich schon tun? Ich bin keine Kämpferin. Ich kann sie nicht rächen. Außerdem hat sich die Erde ihren Leib bereits zurückgeholt. Das erkenne ich an dem Zustand des Fragments ihres Erinnerungsedelsteins.\n\nWas kann ich jetzt tun, außer einen Topf herzustellen? Wollt Ihr mir helfen?", sourceObjective = "Töpfert mit Hreka.", progress = "Ein Leben für die Herstellung von Töpferware. Ist das mein mir von den Titanen gegebenes Schicksal? Wenn ja, warum stelle ich es noch in Frage?", completion = "Fast fertig. Dann müssen wir es im Feuer brennen.", sourceObjectiveStatus = "unverified-source-field" }
quests[79710] = { id = 79710, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Organisierte Organe", description = "Oh! Meine BEINE!\n\nIhr seid perfekt! Ja! Ihr seid ein perfekter, kleiner, unscheinbarer Zweibeiner für meine Arbeit.\n\nDie Alchemie ist mein Handwerk, und ein Alchemist ist nur so gut wie die Zutaten, die er verwendet. Seht Ihr diese Kobyss da unten? Ich kampiere hier draußen schon seit Wochen und beobachte sie.\n\nDie wirken zäher als gewöhnliche Kobyss. Meine Schlussfolgerung? Die müssen aus stärkerem Zeug gemacht sein! Und dieses Zeug will ich! \n\nHier ist ein Sack. Macht ihn bis oben hin voll, voll mit ihren Innereien! So viel Ihr tragen könnt!", sourceObjective = "Füllt den Sack mit Innereien der Kobyss.", completion = "Genial! Fabelhaft!\n\nEin Sack voller Verheißung, Daten und... Arterienschleim.", sourceObjectiveStatus = "unverified-source-field" }
quests[79711] = { id = 79711, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Absolut abscheulich", description = "<Ihr zieht eine vertraut wirkende Gliedmaße aus dem Schlick.\n\nSie scheint nicht unbedingt von einem Kobyss zu stammen, aber vielleicht bringt Euch dieses einzigartige Exemplar eine bessere Belohnung von Al'kubian ein.>", sourceObjective = "Bringt die vertraut wirkende Gliedmaße zu Al'kubian.", progress = "Ooooh! Was ist das?", completion = "Man ist, was man isst.\n\nUnd diese Kobyss ernähren sich von den stärksten Nerubern, die je aufstiegen.\n\nKeine Sorge wegen der Pfützen auf dem Boden... Das ist nur mein Angstschweiß.", sourceObjectiveStatus = "unverified-source-field" }
quests[79713] = { id = 79713, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gossenbad bei Mondschein", description = "Das Bein eines Aufgestiegenen...\n\nEin Stamm der Kobyss, der ein oder zwei Dutzend Wahrgeborene oder Huscher verspeist, vielleicht sogar eine Weisenform wie mich... Aber ein Aufgestiegener ist eine andere Geschichte.\n\nLasst uns das als Intellektuelle angehen und die uns zur Verfügung stehenden Werkzeuge nutzen, um mehr Daten zu sammeln. Welche Werkzeuge haben wir? Euch. Ihr seid das Werkzeug. Ein intellektuelles Werkzeug, das den Kobyss zur Verfügung steht.\n\nTaucht ein in die Tiefen des Sees. Tötet die größten dieser Kreaturen oder ihre Haustiere.\n\nUnd, natürlich, bringt mir ihre Innereien.", sourceObjective = "Sammelt die Eingeweide des Lebersuchers und den Magen des Beinkauers.", progress = "Jegliche Gewinne aus meiner Arbeit fließen direkt in die wissenschaftliche und alchemistische Forschung.\n\nDamit meine ich, dass ich mir die Gewinne selbst auszahle, da ich alchemistischer Forscher bin.", completion = "Ah, ich bitte um Verzeihung. Ich hatte doch noch einen Sack für Innereien übrig. Das wurde mir erst klar, als Ihr schon unterwegs wart...\n\nDavon abgesehen... gut gemacht. Saubere Arbeit. Richtig beeindruckend. Und so weiter.", sourceObjectiveStatus = "unverified-source-field" }
quests[79714] = { id = 79714, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Essen retten", description = "Während ich auf Eure mit Innereien gesegnete Rückkehr gewartet habe, konnte ich einige faszinierende Aktivitäten da unten beobachten. Ein unaufhörlicher Zug aus Kobyss zieht die leblosen Körper meiner Brüder und Schwestern aus dem Wasser des Sees nach Westen in ihre Höhle.\n\nMeine Schlussfolgerung? Neruber werden gejagt und in diesem See aufbewahrt, damit diese Bestien sie verzehren können.\n\nIch werde Euch belohnen, wenn Ihr es schafft, sie vor ihrem Schicksal zu bewahren. Nicht der Forschung wegen, sondern weil es die Moral gebietet.", sourceObjective = "Rettet 5 Gefangene der Kaheti.", completion = "Eure Bemühungen sind willkommen, aber ich kann Euch für zivile Aufgaben... weniger gut entlohnen als für wissenschaftliche Unternehmen.\n\nDaran ist nur mein Stipendium schuld.", sourceObjectiveStatus = "unverified-source-field" }
quests[79715] = { id = 79715, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Großartige, gefräßige Lösungen", description = "Mir fehlt noch eine letzte Information.\n\nDiese Bestien denken. Sie organisieren. Sie koordinieren. Wenn ich ganz ehrlich sein soll, gibt es nichts Schlimmeres als eine Amphibie mit einem Rechenbrett.\n\nMeine letzte Aufgabe für Euch: Bringt mir das Hirn der größten Bestie. Es muss frisch sein und am besten nicht in verflüssigter Form.\n\nUnd, nun ja, vielleicht verlangsamt sie das.", sourceObjective = "Besorgt das Gehirn vom Großen Vielfraß.", progress = "Habt Ihr es dabei? Läuft es aus?", completion = "Fabelhaft! Absolut fabelhaft!\n\nDavon mal abgesehen sind die von Euch gebrachten Proben ziemlich eklig. Kaum zu glauben, dass Ihr für den letzten Teil Eurer Arbeit keinen Sack dabei hattet.\n\nIhr solltet Euch wirklich besser die Hände waschen.", sourceObjectiveStatus = "unverified-source-field" }
quests[79716] = { id = 79716, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Geschichte unter unseren Füßen", description = "Die Titanenschalttafel ist ein großartiger Fund. Und seht euch diese Ruinen an! Hier muss noch mehr sein!\n\nAber die Ausgrabungsstätte ist ein gefährlicher Ort. Brinthe meint, dass Elementare auftauchten, nachdem das Titanengewölbe freigelegt wurde.\n\nElementare mögen keine Ordnungsmagie, aber Titanenrelikte verströmen sie ständig. Sie sind völlig außer sich!\n\nKönnt Ihr rausgehen und ein paar Relikte von den Elementaren zurückholen? Wir müssen bewahren, was wir können!", sourceObjective = "Sammelt 20 zerschmetterte Reliktfragmente von den Elementaren auf Golgrins Insel.", progress = "Schon etwas gefunden?", completion = "Seht Euch all diese Relikte an!\n\nSeht Euch nur diese Geschichte an!\n\nWenn man bedenkt... die Elementare hätten sie einfach zerstört.\n\nEs ist zum Heulen, wirklich!", sourceObjectiveStatus = "unverified-source-field" }
quests[79717] = { id = 79717, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Infiltration mal anders", description = "Ah, schau mal einer an! Genau die Art von krimineller Energie, nach der ich suche.\n\nMein Name ist Ar'syn und ich bin ein Connaisseur der schönen Künste und Geschichte unseres Volks. Ich plane, ins königliche Konservatorium, die große Enklave dort drüben, einzubrechen und es so richtig auszurauben.\n\nDummerweise komme ich wegen der Wachen nicht einmal nah genug heran, um die Sicherheitsvorkehrungen auszuspionieren! Wenn es doch nur irgendjemanden gäbe, der mir hilft, unauffällig ins Gebäude zu gelangen.\n\n<Ar'syn schaut Euch erwartungsvoll an.>", sourceObjective = "Findet drei potenzielle Eingänge ins königliche Konservatorium.", completion = "Man kann über unsere neue Königin sagen, was man will, aber sie weiß echt, wie man für Zucht und Ordnung sorgt. Ständig kommt neue Kriegsbeute im Gebäude an.\n\nVielleicht kann das ja zu unserer Eintrittskarte werden?", sourceObjectiveStatus = "unverified-source-field" }
quests[79718] = { id = 79718, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Straßensonderkommando der Stränge", description = "Ich würde nichts lieber machen, als da reinzugehen und ein paar von diesen aufgeblasenen Royalisten der Sureki auszuschalten. So würde sich unsere Infiltration wesentlich einfacher gestalten. Außerdem würde ihnen das recht geschehen, da sie unsere Geschichte mit Füßen treten. Aber ich komme nicht einmal in die Nähe, ohne dass es in den Strängen zu einer ganzen Schar von toten Wachen kommt.\n\nIhr allerdings? Niemand wird auch nur mit der Wimper zucken, wenn ein Überkrabbler mutwillig Gewalt anwendet. Warum geht Ihr nicht rein und dünnt ihre Reihen aus?\n\nOh, schaut mich nicht so an. Das hattet Ihr doch sowieso gerade vor.", sourceObjective = "Tötet Agenten der Sureki außerhalb des königlichen Konservatoriums.", completion = "Ich bin ganz ehrlich, mein Freund. Rohe Gewalt hat eigentlich nichts mit Kunst gemeinsam.\n\nAber halleluja, bei Euch hatte das etwas von einer Aufführung! Ich bin beeindruckt. Und etwas eingeschüchtert.", sourceObjectiveStatus = "unverified-source-field" }
quests[79721] = { id = 79721, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Achtung, Granate!", description = "Wer seid Ihr? Natürlich, noch ein Fremdling! Ich bin Wenbrandt, Zähmer der Glutbienen und Erfinder des Glutbräu.\n\n<Wenbrandt strafft die Schultern, als sollte Euch das beeindrucken.>\n\nIch habe Fässer mit Glutbräu gebracht, um den Verwundeten zu helfen. Ich dachte, etwas zu trinken würde ihre Schmerzen lindern, aber hauptsächlich hat es mehr... brennende... Schmerzen verursacht.\n\nIch weigere mich, mein Bräu verschwendet zu sehen. Vielleicht kann man es als Waffe einsetzen. Die Neruber sind immerhin nur Käfer - organisch und brennbar.\n\nDieses Erdloch ist genau richtig für einen Test.", sourceObjective = "Nutzt Glutbräu zur Abwehr des nerubischen Angriffs auf das Proszenium.", progress = "Werft ein paar davon auf die Neruber. Mal sehen, was passiert.", completion = "Berge stürzen auf mich herab, das war unglaublich! Stellt Euch vor: Das Zeug haben wir getrunken...", sourceObjectiveStatus = "unverified-source-field" }
quests[79722] = { id = 79722, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gossenarbeit" }
quests[79723] = { id = 79723, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückführung durch Subtraktion", description = "Wie kurzsichtig Ansurek und ihresgleichen doch sind. Sie glauben, wenn wir unser Museum mit den Trophäen ihrer jüngsten Eroberungen statt den Relikten unserer eigenen Geschichte füllen, werden wir weniger geneigt sein, unserer eigenen Herkunft zu gedenken.\n\nNun, sie mögen recht haben, zumindest auf lange Sicht. Die Geschichte hat die Angewohnheit, sich der Stimme ihres Erzählers zu beugen.\n\nAber hier kommen wir ins Spiel, {name}. Es ist an der Zeit, uns die von den Truppen der Sureki geraubten Relikte zurückzuholen.", sourceObjective = "Erbeutet sechs geplünderte Trophäen aus dem Königlichen Repositorium.", progress = "Nun, {name}? ich bin sicher, man hortet dort Schätze, die einer Königin würdig sind.", completion = "<Ar'syns viele Augen funkeln im Höhlenlicht.>\n\nAuch wenn mein Streben heute eher philanthropischen Zielen dient, muss ich gestehen, dass ich einen gediegenen, gekonnt ausgeführten Raubzug durchaus zu schätzen weiß. Seht Euch all diese Schätze an! Ich freue mich schon darauf, sie wieder ihrem angestammten Zuhause zuzuführen.\n\nGegen einen Finderlohn, versteht sich. Stellt Euch vor, die legendären Taschenspielertricks von Azj-Kahet würden zu einer Art Volksheldensage werden?! Gar nicht auszudenken!", sourceObjectiveStatus = "unverified-source-field" }
quests[79724] = { id = 79724, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine titanische Expedition!", description = "Unser Händler hat mir von ein paar kleinen Inseln vor der Nordostküste namens \"Die Drei Schilde\" erzählt.\n\nOffenbar haben die Titanen dort vor langer Zeit viel unternommen. Für mich klingt dieses \"Unternehmen\" nach Forschung und Entwicklung. Wie aufregend!\n\nTuberros und ich werden dorthin fahren und uns alles ansehen. Tharessa, meine neue Auszubildende der Algariexpedition, kommt mit, um echte Profis bei der Arbeit zu erleben.\n\nMöchtet Ihr uns begleiten?", sourceObjective = "Trefft Euch mit Rannan auf den Drei Schilden.", completion = "Alles in Ordnung, mir geht es gut. Ist nur ein Kratzer.\n\nAber wir mussten einen kleinen Gorloc zu dritt ausschalten. Gut, dass Ihr mitgekommen seid.", sourceObjectiveStatus = "unverified-source-field" }
quests[79725] = { id = 79725, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kein Wärmekissen", description = "Tharessa hat sich ein wenig für uns umgesehen und herausgefunden, dass die Gorlocs Artefakte ausgraben und mit ihnen... kuscheln.\n\nDas heißt ja wohl, dass die Artefakte Wärme ausstrahlen? Vielleicht auch, dass ein paar von ihnen noch funktionieren?\n\nStellt Euch vor: Die Titanen erschufen Technologien zum Formen von Welten, und jetzt wärmt sich ein Fisch die Flossen daran. Ha!\n\nDie Gorlocs wollen sie nicht herausrücken, aber ich will auch nicht als Rannan-Kebab enden. Ich frage nur ungern, weil sie es nur warm haben wollen, aber könntet Ihr was gegen sie unternehmen?", sourceObjective = "Rannan will, dass Ihr 12 Gorlocs tötet.", completion = "Wunderbar! Jetzt können wir uns darauf konzentrieren, was wirklich wichtig ist: die Artefakte. Was wir wohl herausfinden werden?", sourceObjectiveStatus = "unverified-source-field" }
quests[79726] = { id = 79726, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "\"Katalogisieren\"", description = "Wie Ihr wisst, sind wir hier, um Titanenglitzerzeug, Artefakte und alles Mögliche zu sammeln!\n\nUnd Rannan glaubt, je mehr etwas glitzert--äh, Ihr wisst, was ich meine--, desto größer ist die Chance, dass wir etwas über die Titanen herausfinden.\n\nDarüber wird Rannan sich freuen, aber auch ich werde anschließend ein paar Artikel mehr in meinem Laden stehen haben.\n\nMeine Frau Perisimona erwartet sie schon zu Hause in Loamm. Ich kann nicht mit leeren Händen zurückkehren!", sourceObjective = "Beschafft 7 Titanenartefakte.", progress = "Habt Ihr schon ein bisschen Glitzerzeug?", completion = "<Tuberros sieht sich die Titanenartefakte an.>\n\nDas hier riecht sehr säuerlich... und ist kaputt. Ich kann es in den Laden bringen... Rannan würde sich das hier gerne anschauen... Ja, die sind hervorragend. Danke, dass Ihr sie mir gebracht habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[79727] = { id = 79727, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weil es glänzt", description = "Während die beiden Euch herumkommandiert haben, habe ich mir gedacht, dass ich mich am besten nützlich mache und dafür sorge, dass die Gorlocs uns hier nicht am Strand überraschen.\n\nKeiner von denen schien sich für uns zu interessieren, doch dann habe ich einen riesigen Gorloc gesehen.\n\nEr brachte ein paar kleinere der Gorlocs um und verschwand dann. Er hatte dabei irgendetwas Leuchtendes in seiner Klaue!\n\nDas war ganz sicher ein Artefakt. Und es sah aus, als würde es funktionieren! Wir müssen es uns holen.\n\nUnd mit \"wir\" meine ich \"Euch\". Überdurchschnittlich große Gorlocs werden nicht von meinem Drachenschuppensold abgedeckt.", sourceObjective = "Beschafft das Artefakt von dem riesigen Gorloc.", progress = "Habt Ihr das Artefakt besorgen können?", completion = "Ich kann es von hier aus summen hören. Au. Das tut mir in den Ohren weg.\n\nMal sehen, ob unsere beiden \"Profis\" Rannan und Tuberros wissen, was das für ein Artefakt ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[79728] = { id = 79728, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ist wahrscheinlich gar nichts", description = "Ihr habt eine Summkugel gefunden!\n\n...Äh, so nennen die Niffen das Ding. Ich habe das einfach übernommen.\n\nSie ist noch in gutem Zustand. Sie summt und brummt noch und fühlt sich warm an! So etwas habe ich zuletzt in der Zaralekhöhle gesehen!\n\n{name}, seht mal, ob Ihr die Kugel zum Funktionieren bringen könnt. Ich halte ein wenig Abstand für den Fall, dass sie uns, äh, nicht freundlich gesinnt ist.\n\nAber da brauchen wir uns sicher keine Sorgen zu machen.", sourceObjective = "Interagiert mit der Titanenkugel.", progress = "Ja, ja! Ich freue mich schon darauf zu hören, was Ihr herausgefunden habt.", completion = "Alphastandort? Verteidigungsraster?\n\nDas klingt gar nicht gut.\n\nWir sollten aufbrechen. Ich will nicht hier sein, wenn ihre Freunde zurückkehren, um sie abzuholen.\n\nAuf dieser Wiedersehensfeier will ich nicht tanzen.\n\nHoffentlich nimmt sie Tharessa nicht ins Visier... Nein, wahrscheinlich nicht. Auf jeden Fall sollten wir los. Und zwar sofort.\n\nBis dann, {name}. Danke für Eure... Hilfe? Kann ich das so sagen?", sourceObjectiveStatus = "unverified-source-field" }
quests[79729] = { id = 79729, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Selbststudium", description = "Die Gründungsrelikte waren von jeher das Herzstück der Sammlung im Konservatorium. Zusammen erzählen diese vier Artefakte unsere ehrwürdigste Geschichte: die der Gründung von Azj-Kahet und der Lossagung unseres Volks von den alten Meistern.\n\nMit etwas Glück sind sie noch im Konservatorium. Sobald Ihr hineingelangt seid, manipuliert die Schattenwerfer vor den Relikten. Sorgt dafür, dass ihre Botschaften von allen im Umkreis vernommen werden, ob sie sie hören wollen oder nicht.", sourceObjective = "Manipuliert die Schattenwerfer vor jedem der vier Gründungsrelikte.", completion = "Und da haben wir sie. Eine brillante Visitenkarte für unsere Pläne und eine hervorragende Ablenkung, um unsere Flucht zu verschleiern. Alles in einem praktischen, lehrreichen Paket!\n\n...Wenn das nur alles gute Nachrichten wären. Unsere Fluchtstrategie ist kompliziert geworden.", sourceObjectiveStatus = "unverified-source-field" }
quests[79730] = { id = 79730, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hartnäckige Verfolgung", description = "Aber natürlich reicht es nicht, die Relikte einfach zu stehlen. Wir müssen den Lieblingswürmern der Königin beibringen, was Zwecklosigkeit bedeutet, ansonsten fangen sie einfach wieder von vorne an!\n\nDieser großmäulige Witzbold am Hauptgang ist Rez'kal, ein Mitglied von Ansureks persönlichem Gelehrtengefolge. Er ist... nicht der Klügste, aber das macht er durch eine Stärke wett, mit der er jeden von uns durch eine Wand werfen könnte.\n\nIch bin heute wenig geneigt, mich mit diesem Riesentrampel anzulegen. Würdet Ihr mir wohl einen letzten Gefallen tun?", sourceObjective = "Besiegt den königlichen Vermittler Rez'kal.", progress = "Seid vorsichtig, {name}. Was Rez'kal an Scharfsinn fehlt, macht er mit panzerköpfiger Sturheit wett.", completion = "Ah! Da seid Ihr ja. Gute Arbeit mit dem Trottel vorhin. Er war zwar vielleicht ein Narr, aber ein Narr mit sehr scharfen Klingen an seinen Armen.\n\nGut, mit den Reliquien in der Hand ist es Zeit für meinen großen Abgang. Schließlich gibt es noch eine Menge gestohlener Reichtümer, die ich mir wieder zurückholen muss! Aber ich habe unsere Zusammenarbeit sehr genossen. Mit etwas Glück kreuzen sich unsere Wege vielleicht bald wieder.", sourceObjectiveStatus = "unverified-source-field" }
quests[79944] = { id = 79944, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rasende Risse", description = "Die Elementare kommen aus dem Inneren dieser Höhle. Wir konnten nur ein Stück vordringen, bevor wir uns zurückziehen mussten. \n\nIch konnte dort ein Flackern erkennen, ein merkwürdiges, leuchtendes Ding, fast schon wie eine Art Riss im Raumzeitgefüge, aus dem die Elementare herausströmen! Eines dieser Portale konnten wir schließen, doch es gibt noch mehr.\n\nIch muss bei Nanthaz bleiben. Es liegt nun an Euch. Wenn Ihr könnt, zerstört die Risse und findet ihren Ursprung. Ich vermute, dass er sich tiefer im Inneren der Höhle befindet.", sourceObjective = "Zerstört 4 Risse und findet ihren Ursprung in der Höhle.", completion = "Ihr kehrt hoffentlich mit guten Nachrichten zurück?\n\n<Ihr erzählt ihr von Urthgrafr Rissrufer.>\n\nNach Urthgrafrs Niederlage dürften wir keine Probleme damit haben, die restlichen Elementare und Risse selbst zu beseitigen. Wir hatten Glück, dass Ihr zur rechten Zeit herkamt.\n\nDanke für Eure Hilfe. Macht Euch keine Sorgen um Nanthaz und mich. Sobald er wieder zu Atem gekommen ist, werden wir uns zur Raffinerie durchschlagen. Vielen Dank, Fremdling. Und mögen alle Irdenen eines Tages erwachen.", sourceObjectiveStatus = "unverified-source-field" }
quests[79954] = { id = 79954, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spinnen!", sourceObjective = "Findet Ag'thax' vermissten Schlüssel in Stütznest Xesh.", progress = "Lasst Euch nicht von den Spinnen fressen, bevor Ihr mit meinem Schlüssel entkommt.", completion = "Keine Details, ich muss nicht wissen, wo Ihr ihn gefunden habt.\n\nIch kann es kaum erwarten, meinen Bau in den Hochhöhlen zu beziehen!", sourceObjectiveStatus = "unverified-source-field" }
quests[79955] = { id = 79955, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "...und jetzt auch noch Arachnophobie", description = "Wer ist da? Ist da wer? Habe ich mir Euch nur eingebildet?\n\nIch bin Albert. Einst war ich ein Pfadfinder. Aber jetzt, wo ich blind bin, sehe ich keine Pfade mehr. Es scheint mir unangemessen, mich noch Pfadfinder Henson zu nennen. Aber hören kann ich. Ich höre sie fressen. Sie laben sich an den frischen Körperteilen.\n\nAn meinen Augen, meinen Eingeweiden.\n\nDie Schmerzen lassen nie nach. Meine verfaulten Teile wollen sie nicht. Nur sie wurden mir gelassen. Mein schäbiger Rest.\n\nIch war nicht allein. Es waren noch andere Pfadfinder hier. Immer wieder höre ich das Schluchzen von den Mauern hallen. Hört Ihr es auch?", sourceObjective = "Findet Alberts Freunde in den Mauern.", completion = "Sie sind also tot...", sourceObjectiveStatus = "unverified-source-field" }
quests[79956] = { id = 79956, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beinchen an der Decke", description = "Ich möchte keine Rache für mich selbst, nur für alle meine Freunde, die gefressen wurden. Ich hielt den Schrecken von Xesh nicht für real, doch das ist er. Xishirra. Ein Schatten eines Alptraums, der eine Monsterbrut erschafft und selbst unerreichbar ist.\n\nDer Schrecken ist uralt und überweltlich, doch wir können es Xesh dennoch heimzahlen! Zieht fest an einer Netzfaser, wenn Ihr müsst, und bezwingt, was auch immer Ihr dadurch anlocken mögt. Sobald der Gerechtigkeit genüge getan ist, fliehen wir.", sourceObjective = "Zieht am Spinnenfaden, falls die Spinnen Euch nicht bereits angreifen, und tötet, was auch immer kommt.", completion = "<Alberts Augen hatten sich bereits verdunkelt, doch nun ist auch der letzte Lebensfunke aus seinem restlichen Körper gewichen.>", sourceObjectiveStatus = "unverified-source-field" }
quests[79957] = { id = 79957, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Maden in den Augen", description = "<Albert ist nicht mehr am Leben. Zurück bleibt nur sein Kopf, der immer noch voller Maden ist.\n\nIhn zu den Pfadfindern zurückzubringen, scheint das Richtige zu sein.>", sourceObjective = "Bringt Alberts Kopf zu den Pfadfindern in Faerins Vorstoß.", progress = "Wessen Kopf ist das?", completion = "Dieser größtenteils aufgefressene, madige Kopf ohne Augen ist...\n\nAlbert! Oh nein, was ist passiert?!\n\nWir wussten nicht, wo sein Team hingegangen ist, nur, dass es um eine Mission nahe der Stadt ging. Ich kann mir gar nicht ausmalen, welche Schmerzen er erlitten haben muss oder was Ihr auf Euch nehmen musstest, um uns seine Überreste zu bringen. Wir übernehmen ab hier. Danke, dass Ihr ihn zurückgebracht habt.\n\nUnd ich hoffe, dass Ihr nicht lange von Alpträumen geplagt sein werdet.", sourceObjectiveStatus = "unverified-source-field" }
quests[79958] = { id = 79958, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Entwurmt, versiegelt, geliefert" }
quests[79959] = { id = 79959, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Welt der Wurmkraft" }
quests[79960] = { id = 79960, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einmal zum Mitnehmen" }
quests[79965] = { id = 79965, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lernt, wie es läuft, oder geht über die Planke" }
quests[79989] = { id = 79989, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein uraltes Erwachen", description = "Das Portal liegt direkt hinter mir. Schwer zu sagen, wie viel Zeit noch bleibt, bis die schwindende Verzauberung des Gefäßes komplett versiegt oder, schlimmer noch, bricht.\n\nDie dann freigesetzte instabile Energie kann katastrophale Folgen haben.\n\nWollen wir fortfahren?", sourceObjective = "Ermächtigt das Portal.", completion = "Jetzt, da wir, und mit wir meine ich Euch, herausgefunden haben, was diese Dinger sind, bleibt trotzdem unklar, wie viele es davon gibt!\n\nHaltet Eure Augen offen, {name}. Wer weiß, was wir auf den Inseln sonst noch finden.", sourceObjectiveStatus = "unverified-source-field" }
quests[79998] = { id = 79998, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Milbe nicht milde", description = "Das nicht gut. Hübsche Feuerbienen haben Milben!\n\nJanky hat das schon mal gesehen. Stock wird befallen, gute Käfer werden ausgesaugt. Schlimmes Ende. Müssen etwas tun!\n\nPusten Rauch auf Bienen. Macht sie schläfrig, aber Milben das hassen!\n\nWenn sie abspringen, Ihr sie zerquetschen, bevor sie Bienen wieder beißen.", sourceObjective = "Reinigt Feuerbienen mit Jankys Duftrauch von ihrem Befall und tötet die störenden Milben.", progress = "Viele Milben übrig?", completion = "Nur tote Milbe gute Milbe. Gute Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[79999] = { id = 79999, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hoffnung entzünden", description = "Unser Dämmerturm ist gefallen, aber dank der kleineren Schlüsselflamme auf der Mauer bleibt ein schwacher Funke Hoffnung.\n\nDie zerschmetterten Überbleibsel, die das Licht nähren, wurden von den Nerubern mitgenommen.\n\nHolt die Überbleibsel von den Nerubern zurück, die Ihr tötet, und helft dabei, ein Leuchtfeuer der Hoffnung zu entzünden!", sourceObjective = "Sammelt 5 zerschmetterte Überbleibsel und stärkt damit die Schlüsselflamme der Aegis.", progress = "Eine ermächtigte Schlüsselflamme wird uns eine große Hilfe sein.", completion = "Das Licht der Flamme gibt mir Hoffnung, dass wir die Neruber zurückdrängen!", sourceObjectiveStatus = "unverified-source-field" }
quests[80000] = { id = 80000, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bienenbeißer", description = "Milben töten Feuerbienen. Nix gut!\n\nJanky hasst Milben. Beißen einen, auch wenn keinen Wachs stehlen. Nicht mal Wachs machen!\n\nBienen verdienen Chance. Ihr töten größte, bissigste Milbe, bevor mehr Bienen frisst.", sourceObjective = "Tötet Bienenbeißer.", progress = "Wie Brennen sich anfühlen? Gut?", completion = "Feuerbienen jetzt sicher. Hier sein, wenn später wiederkommen für mehr Wachs.", sourceObjectiveStatus = "unverified-source-field" }
quests[80004] = { id = 80004, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Krabbe schnappen", description = "<Die Ankunft der Kobyss hat die Arathi davon abgehalten, diese Küste zu erschließen. Ihnen einen Käfig voll frischer Krabben zu bringen, würde den hungrigen Bürgern helfen.>", sourceObjective = "Sammelt 12 Schattenflutkrabben im Gewässer vor der Verblassten Küste.", sourceObjectiveStatus = "unverified-source-field" }
quests[80005] = { id = 80005, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Krabbe schnappen - Aktivieren" }
quests[80012] = { id = 80012, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Himmelsreiten", description = "Dieses Land ist größer, als ich es in Erinnerung hatte. Eine gute Gelehrte bereitet sich allerdings immer auf alle Eventualitäten vor.\n\nZwei der im Flug versiertesten Drachen haben zugestimmt, uns zu helfen. Sie werden ein geflügeltes Reittier bereitstellen, damit Ihr größere Gebiete abdecken könnt.\n\nIch werde Euch zu Lord Andestrasz schicken. Er wird weitere Anweisungen für Euch haben.", sourceObjective = "Nehmt Morataris Portal zu Lord Andestrasz.", progress = "Mit der Zeit kommt die Übung.", completion = "Lasst uns anfangen.\n\nKeine Sorge, die aufregenden Manöver kommen erst später.", sourceObjectiveStatus = "unverified-source-field" }
quests[80013] = { id = 80013, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drachenflug leicht gemacht", description = "Fangen wir mit den Grundlagen an.\n\nWenn Ihr geradeaus fliegt, werdet Ihr sehr schnell erschöpft sein. Nutzt die Schwerkraft und zielt leicht nach unten, um eine lange Strecke zu fliegen. Die Ringe zeigen Euch den allgemeinen Winkel an, den Ihr für den einfachen Gleitflug verwenden solltet.\n\nZuerst, ruft Euren Drachen herbei. Alternativ kann unser roter Drachenfreund hier Euch mitnehmen.\n\nDann fliegt durch die Ringe und landet am Zielort.\n\nWenn Ihr irgendwo festhängt, benutzt die bronzene Taschenuhr und Celormu wird Eure Position zurücksetzen.", sourceObjective = "Beschwört Euren Reitdrachen oder steigt auf den roten Drachen. Gleitet anschließend durch die Ringe und landet im Zielgebiet.", completion = "Exzellente Arbeit!", sourceObjectiveStatus = "unverified-source-field" }
quests[80015] = { id = 80015, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drachensturzflug leicht gemacht", description = "Gleitend erreicht Ihr das gewünschte Ziel. Aber was, wenn Ihr schneller ankommen wollt?\n\nDurch den Sturzflug von einem hohen Punkt erhaltet Ihr einen Geschwindigkeitsschub. Wenn Ihr das Fliegen beherrscht, könnt Ihr Euren Schwung beibehalten und nach einem Sturzflug etwas an Höhe gewinnen.\n\nFliegt durch die Ringe zum Zielort.\n\nWenn Ihr irgendwo festhängt, benutzt die bronzene Taschenuhr und Celormu wird Eure Position zurücksetzen.", sourceObjective = "Führt einen Sturzflug aus, gleitet dann durch die Ringe und landet im Zielgebiet.", completion = "Seht Ihr? Das war viel besser.\n\nWenn Ihr den Flug mit einem Sturzflug beginnt, kommt Ihr viel schneller an das gewünschte Ziel.", sourceObjectiveStatus = "unverified-source-field" }
quests[80016] = { id = 80016, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geschwindigkeitsrausch", description = "Manchmal werdet Ihr weitere Strecken zurücklegen müssen.\n\nWenn Ihr keine Hindernisse überwinden müsst, ist 'Vorwärtsschub' die einfachste Möglichkeit, eine gute Geschwindigkeit beizubehalten, damit Ihr nicht abstürzt.\n\nFolgt wieder den Ringen zum Ziel und nutzt 'Vorwärtsschub', wenn Ihr aufgefordert werdet, Eure Geschwindigkeit zu halten.\n\nWenn Ihr feststeckt, nutzt die bronzene Taschenuhr, dann wird Celormu Euch zurücksetzen.", sourceObjective = "Fliegt durch die Ringe und landet im Zielgebiet.", completion = "Gut gemacht.\n\nDer Rest ist nur eine Frage der Übung.", sourceObjectiveStatus = "unverified-source-field" }
quests[80017] = { id = 80017, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Höhenrausch", description = "Setzt 'Aufstieg gen Himmel' ein, um an Höhe zu gewinnen.\n\nFolgt den Ringen erneut, um Euer Ziel zu erreichen, und setzt 'Aufstieg gen Himmel' ein, wenn Ihr Schwung nach oben braucht.\n\nWenn Ihr nicht weiterkommt, setzt die bronzene Taschenuhr ein, dann setzt Celormu Euch zurück.", sourceObjective = "Fliegt durch die Ringe und landet im Zielgebiet.", completion = "Stets nach oben werdet Ihr gehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[80018] = { id = 80018, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Todschickes Fliegen", description = "Ihr habt alles gelernt, was ich Euch beibringen kann.\n\nAber beim Fliegen geht es nicht nur darum, Euer Ziel zu erreichen, sondern auch darum, stilvoll dort anzukommen!\n\nBenutzt das Podium der Transformation hinter Euch, um das Aussehen Eures Drachen anzupassen.", sourceObjective = "Benutzt das Podium der Transformation.", completion = "Jetzt seid Ihr bereit zum Fliegen.\n\nAb mit Euch, viel Glück auf Eurer Reise!", sourceObjectiveStatus = "unverified-source-field" }
quests[80022] = { id = 80022, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Sturmreiter rufen", description = "Ich weiß, dass die Freien den Kernweg schnell reparieren und freigeben können - aber ich kenne auch die Neruber. Wenn sie eine Gelegenheit für einen Hinterhalt sehen, werden sie sie nicht ungenutzt lassen.\n\nWenn wir ihnen den Rücken kehren und uns auf den Kernweg konzentrieren, sind wir leichte Ziele.\n\nIch muss meine Sturmreiter versammeln und eine Abgrenzung um Dornogal errichten, für den Fall eines Angriffs von innen oder außen.\n\nWir treffen uns vor dem Sturmhort. Dort werde ich meine Truppen zusammenrufen.", sourceObjective = "Trefft Baelgrim außerhalb des Sturmhorts, sprecht mit ihm und folgt ihm zur Brutstätte.\n\nDiese Herausforderung kann solo oder mit bis zu 3 Gruppenmitgliedern bestritten werden.", progress = "Baelgrim hat recht. Wir müssen die Freien verteidigen, während sie am Kernweg arbeiten.", completion = "Die gesamte Brutstätte?\n\nVerstehe.\n\nWenigstens ist die Quelle vernichtet. Ich bedaure den Verlust der vielen Sturmreiter, doch...\n\nWenn die Verderbnis Dornogal erreicht hätte...", sourceObjectiveStatus = "unverified-source-field" }
quests[80049] = { id = 80049, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Flamme brennt noch", description = "Das war viel zu knapp.\n\nDieser Angriff hat uns allen zugesetzt. Viele sind verletzt, viele zerrüttet.\n\nKönnt Ihr nach den Leuten schauen? Sehen, wie es ihnen geht?", sourceObjective = "Schaut nach Überlebenden der Arathi in den Ehrengründen in Heilsturz.", completion = "Der Wille der Arathi lässt sich nicht brechen!", sourceObjectiveStatus = "unverified-source-field" }
quests[80058] = { id = 80058, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Koboldbereinigung", description = "Neues Heim bisschen schäbig. Nicht gut, voll mit komischen Sachen und abgeranzt. Alt. Alle gestorben. Und jetzt fällt auseinander.\n\nWir helfen! Viele Kobolde jetzt da, wir Haus herrichten für Steinkopffreunde. Damit fühlen sich zu Hause.\n\nIhr auch helfen! Besen nehmen, loslegen!", sourceObjective = "Räumt Gundargaz auf.", progress = "Wie gehen?", completion = "Viel besser. Echsen lecker, aber nicht wollen, dass über gute Teppiche laufen.", sourceObjectiveStatus = "unverified-source-field" }
quests[80069] = { id = 80069, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teldrassils Tränen", description = "Ich habe diese Last lange genug getragen. Es ist endlich an der Zeit, meine Familie zur Ruhe zu betten. Auch wenn ich meine Schwester nie finden konnte...\n\n<Kelestra wischt sich die Tränen ab und nimmt einen tiefen Atemzug.>\n\nIch muss Grabhügelsteine finden und sie an ihrer letzten Ruhestätte aufstellen. Aber ich kann so viele Steine einfach nicht tragen.\n\nEs mag eine unverblümte Bitte an jemand Fremden sein, aber würdet Ihr mir wohl helfen? Die Bürde wird mir sicher leichter fallen, wenn ich dabei eine gute Seele an meiner Seite weiß.", sourceObjective = "Folgt Kelestra und sammelt Grabhügelsteine, damit sie ihrer Familie ein würdiges Denkmal setzen kann.", completion = "<Kelestra nimmt einen tiefen Atemzug, um sich zu beruhigen.>\n\nKoroleth... Was hast du nur getan? Und warum? Ich muss wissen, warum!", sourceObjectiveStatus = "unverified-source-field" }
quests[80071] = { id = 80071, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spurensuche", description = "Ich muss mit den Primalisten sprechen. Ich verstehe nicht, warum sie sich gegen uns wenden sollte.\n\nKoroleth hat mir bei Teldrassil das Leben gerettet. Ich bin es ihr schuldig, die Wahrheit herauszufinden.\n\n{name}, ich möchte Euch nicht in Verlegenheit bringen, aber würdet Ihr mir helfen? Allein schaffe ich es nicht mehr.", sourceObjective = "Trefft Euch mit Kelestra am Zwielichtswachturm.", completion = "Danke, dass Ihr gekommen seid, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[80072] = { id = 80072, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aus der Sicht eines Primalisten", description = "Wächterin Malathra hat uns erlaubt, mit den Primalisten zu sprechen. Sie mögen die Seiten gewechselt haben, aber die Wächter behalten sie dennoch genau im Auge.\n\n<Kelestra wirkt bekümmert.>\n\nIch werde weiter mit der Wächterin sprechen. Könnt Ihr Euch um die Primalisten kümmern? Diese ganze Sache mit Koroleth, das kommt alles so plötzlich. Wir sollten so viele Informationen zusammentragen wie möglich.", sourceObjective = "Sprecht mit den geläuterten Primalisten über Koroleth.", progress = "Ich würde ja gerne selbst mit ihnen sprechen, aber ich wüsste nicht einmal, wo ich anfangen soll.", completion = "Was konntet Ihr herausfinden?\n\n<Kelestra hört Euch angespannt zu, als Ihr wiedergebt, was Ihr erfahren habt.>\n \nIch kann verstehen, dass meiner Schwester nichts lieber wäre, als die gesamte Horde zu vernichten. Ich selbst wie auch viele andere von uns, wir alle hatten diese Gefühle für eine Weile. Und Koroleth war schon immer extrem auf ihre Ziele fixiert.\n\nIch glaube jedoch auch, dass sie sofort die Seiten gewechselt hätte, hätte sie von Amirdrassil gewusst.", sourceObjectiveStatus = "unverified-source-field" }
quests[80073] = { id = 80073, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Knochen einer längst vergangenen Schlacht", description = "Im Gespräch mit dem Wächter fand ich heraus, dass die Schlacht um die Barriere, bei der meine Schwester zu Tode kam, östlich von hier stattfand, an der Küste der Ebenen von Ohn'ahra.\n\nIhr Leichnam wurde wohl von den Gezeiten hinaus aufs Meer gezerrt und wurde nie gefunden.\n\nGut möglich, dass ihre Überreste zu einem späteren Zeitpunkt wieder an Land gespült wurden. Werdet Ihr mir helfen, nach ihr zu suchen?\n\nJedes Mitglied meiner Familie trägt exakt so eine Halskette. So können wir Koroleths Leichnam leicht identifizieren.\n\nIch würde sie gerne neben ihrer geliebten Familie zur Ruhe betten.", sourceObjective = "Sucht an der Küste des Uralten Zweigs nach Koroleths Überresten.", progress = "Ist das die Halskette, die Ihr gefunden habt?", completion = "Oh Koroleth...\n\n<Kelestra blickt traurig auf das, was von ihrer Schwester übrig geblieben ist, und schluchzt leise.>", sourceObjectiveStatus = "unverified-source-field" }
quests[80075] = { id = 80075, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Letzte Ruhe im Hügelgrab", description = "Mir bleibt nur übrig, die Überreste meiner Schwester mitzunehmen und zum Hügelgrab zu bringen.\n\nBitte trefft mich dort, {name}. Ich kann einen Freund gebrauchen.", sourceObjective = "Trefft Euch mit Kelestra vor dem Grabhügel auf den Feldern der Tagträume.", completion = "<Kelestra ist den Tränen nahe.>\n\nSie verwehren mir den Zutritt. Nach allem, was wir für sie getan haben, weigern sie sich, meiner Schwester ihre letzte Ruhe zu gestatten!", sourceObjectiveStatus = "unverified-source-field" }
quests[80077] = { id = 80077, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sünden der Schwester", description = "Dieser Druide tut alles, um Malfurion davon zu überzeugen, dass meine Schwester nicht neben meinen anderen Familienmitgliedern hier beerdigt werden soll. Er lässt mich nicht einmal zu Wort kommen.\n\n<Kelestra klammert sich fest an die Riemen ihres Rucksacks, in dem sich die Überreste ihrer Schwester befinden.>\n\nIch weiß, ich habe bereits viel von Euch verlangt, aber könntet Ihr vielleicht mit ihnen sprechen? Womöglich schenken sie Euch ja Gehör?", sourceObjective = "Sprecht mit Malfurion Sturmgrimm wegen Koroleths sterblichen Überresten.", completion = "Das war keine leichte Entscheidung, aber ich halte sie für die richtige.\n\nDanke, dass Ihr Kelestra bei dieser Angelegenheit unterstützt habt. Hoffen wir trotz der Umstände, dass der Fund ihrer Schwester es ihr möglich macht, nun mit diesem Kapitel abzuschließen.", sourceObjectiveStatus = "unverified-source-field" }
quests[80079] = { id = 80079, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Schraubenschlüssel im Getriebe", description = "Anscheinend richtet sich der Oberste Sprecher an seine Arbeiter. Es scheint, als hätte sie etwas aus ihrer Bequemlichkeit gerüttelt und dass die Zeit, die sie der Erweckungsmaschine fern waren, etwas mit ihnen macht.\n\n<Moira hält inne, um etwas Staub von ihrer Robe zu wischen.>\n\nVielleicht wäre das eine gute Gelegenheit für alle, zu hören, was sie zu sagen haben.\n\nWir sollten ein paar dieser Maschinenflüsterer davon überzeugen, den Mund aufzumachen.", sourceObjective = "Ermutigt Personen in der Menge, ihrem Ärger Luft zu machen.", progress = "Störrischer Haufen, nicht wahr?", completion = "Ausgezeichnet, jetzt machen wir endlich Fortschritte.", sourceObjectiveStatus = "unverified-source-field" }
quests[80081] = { id = 80081, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Befehle des Kapitäns: Flut und fette Beute" }
quests[80082] = { id = 80082, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr nach Gundargaz", description = "Wir haben den Kerzenkönig zwar nicht gestürzt, aber unsere Arbeit hier hat Gundargaz gewiss ein wenig entlastet. Und wir haben nicht wenige neue Verbündete gewonnen.\n\nWir werden unsere neuen Freunde nicht vergessen, darauf gebe ich mein Wort als Sprecherin. In Gundargaz gibt es in letzter Zeit... freien Wohnraum in einem bedauerlichen Ausmaß. Es ist schön, wenn die Stadt wieder zum Leben erwacht, und wir können die Arbeitskräfte sicher gut gebrauchen.\n\nSollen wir sie nach Hause holen, {name}?", sourceObjective = "Kehrt nach Gundargaz zurück.", completion = "Ich bin froh, wieder hier zu sein, doch diese Zusammenkunft ist... beunruhigend.\n\nDer Unmut scheint zuzunehmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[80096] = { id = 80096, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schaufel im Stein", description = "Und jetzt wir gehen suchen legendäre Klinge! Wer sie aus dem Stein ziehen, in dem sie stecken, für Größe bestimmt ist.\n\nEinziges Problem: Stecken sehr fest. In sehr großem Stein. Nicht mal wissen, wie wir überhaupt hinkommen.\n\nKommt! Wir Eure Hand auf Schicksalsprobe stellen!", sourceObjective = "Beschafft Euch die legendäre Koboldschaufel Exkavator.", progress = "Aus den Knien ziehen, nicht aus Rücken.", completion = "Ihr für große Dinge bestimmt, {name}. Schaufel ist Beweis!", sourceObjectiveStatus = "unverified-source-field" }
quests[80110] = { id = 80110, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tägliche Dublonen" }
quests[80144] = { id = 80144, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Heilige Blecheimer", description = "Unheiler Gral eins der allerbesten Relikte sein. Lange Zeit verloren gewesen, {name}. Sehr alt, sehr mächtig.\n\nViel bedeuten würde, wenn finden.\n\nEuch auf große Quest für Suche nach Unheiler Gral schicken!\n\nBei Fischich anfangen. Fischich richtig alt, vielleicht was wissen. Ihn bei Teichen in Nordosten aufsuchen.", sourceObjective = "Findet den unheilen Gral.", progress = "Ihr Gral haben?", completion = "Noch unheiler als in Erinnerung. Und mehr Fischschleim.", sourceObjectiveStatus = "unverified-source-field" }
quests[80145] = { id = 80145, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Hauptader", description = "<Zet-Zets Kern beginnt leise zu summen, als der Projektor Betriebstemperatur erreicht.>", sourceObjective = "Aktiviert die übrigen Zermalmer in der Schattenaderhöhle.", progress = "<Zet-Zet blickt zu Euch auf.>", completion = "<Zet-Zet sieht bereit aus, zu den Golemwerken der Tiefenschmiede zurückzukehren.>", sourceObjectiveStatus = "unverified-source-field" }
quests[80175] = { id = 80175, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der letzte Magier", description = "Ich möchte Euch bitten, nach jemandem zu sehen. Er ist ein Magier... der einzige in unseren Reihen. Alle anderen sind beim Absturz gestorben.\n\nEr versucht, ein Portal nach Hause ins Reich zu erschaffen, damit wir Verstärkung anfordern und ins Reich und wieder zurück reisen können.\n\nWir wissen alle, dass es ein vergebliches Unterfangen ist, aber er will einfach nicht aufgeben.\n\nVielleicht würde ihm ein Gespräch mit <einem erfahrenen Reisenden/einer erfahrenen Reisenden> die Tatsachen vor Augen führen. Würdet Ihr ihm ins Gewissen reden?", sourceObjective = "Findet Wenren Althal in Beledars Schatz.", completion = "Was? Wer hat Euch geschickt? \n\nEs ist egal, hört zu! Ich stehe so kurz vor dem Durchbruch, ich kann ihn schon fühlen!", sourceObjectiveStatus = "unverified-source-field" }
quests[80176] = { id = 80176, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arkane Rinnsale", description = "Ich habe es fast!\n\nIch erschaffe einen neuartigen Teleportationszauber, damit wir zurück ins Reich kommen.\n\nDiese Krabben könnten der Schlüssel sein. Sie verströmen pure arkane Teleportationsmagie!\n\nIch brauche weitere Proben, die ich studieren kann.\n\nNehmt diesen Fokus. Damit könnt Ihr arkane Spuren sehen. Es gibt hier nicht viele andere arkane Quellen, also sollten Euch sämtliche Spuren direkt zu den betroffenen Krabben führen!", sourceObjective = "Beschafft 5 arkangeflutete Organe von Uferkriechern in der Nähe von Mereldar.", progress = "Habt Ihr die Krabben gefunden? Sie halten sich in der Nähe von Gewässern auf. Mit diesem Fokus müsstet Ihr die Spuren des Arkanstaubs sehen können, die sie hinterlassen.", completion = "Ja, die sind perfekt!", sourceObjectiveStatus = "unverified-source-field" }
quests[80177] = { id = 80177, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arkane Experimente", description = "Das ist es! Die knisternde Energie dieser Krabben ist erfüllt von Teleportationsmagie! Ich muss sie nur extrahieren und die Formel anpassen...\n\nIch schaffe das, <mein neuer Freund/meine neue Freundin>! Mir fehlt nur noch eine zusätzliche Hand. Helft Ihr mir, das zu testen?", sourceObjective = "Helft Wenren bei seinen Experimenten.", completion = "<Wenrens leblose Augen blicken zu Euch auf.>", sourceObjectiveStatus = "unverified-source-field" }
quests[80178] = { id = 80178, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein schrecklicher Mord", description = "<Irgendjemand wollte nicht, dass Wenren seinen Zauber vollendet.\n\nFindet heraus, wer.>", sourceObjective = "Untersucht den Mord an Wenren.", progress = "<Der Körper ist noch immer warm.>", completion = "<Ihr begutachtet Eure gefundenen Hinweise sorgfältig.>", sourceObjectiveStatus = "unverified-source-field" }
quests[80179] = { id = 80179, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spuren der Gerechtigkeit", description = "<Die Einzelteile ergeben zusammen ein einfaches, aber düsteres Bild.\n\nDer Orden der Nacht wollte verhindern, dass Wenren ein Portal zurück ins Reich erschafft. Verstärkungen und Vorräte würden seine Mission zweifellos behindern.\n\nAlso erstach jemand Wenren, verbrannte seine Forschung und zerstörte seine Werkzeuge.\n\nIn diesem arkanen Fokus in Euren Händen entdeckt Ihr jedoch eine schwache Spur arkaner Rückstände. Hat der Täter womöglich ein wenig arkanen Staub abbekommen?\n\nFolgt der Spur und findet es heraus.>", sourceObjective = "Spürt Wenrens Mörder auf.", completion = "<Stahlstoß hört Euch mit wachsender Besorgnis zu.>\n\nNein! Tot?!", sourceObjectiveStatus = "unverified-source-field" }
quests[80183] = { id = 80183, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stücke Hass" }
quests[80184] = { id = 80184, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beständigkeit im Kampf", description = "Auf dem Schlachtfeld gibt es einiges zu lernen, selbst in unkoordinierten Umgebungen. Nur zu, versucht es mal.", sourceObjective = "Verdient Ehre auf zufälligen Schlachtfeldern.", completion = "Seht Ihr? So schlimm war das doch nicht. Nehmt das hier als kleine Entschädigung.", sourceObjectiveStatus = "unverified-source-field" }
quests[80185] = { id = 80185, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beständigkeit alleine", description = "Alleine zu kämpfen, fördert Eure Stärke und Tapferkeit. Beweist Eure eigenständigen Fähigkeiten in kleinen Schlachten und kehrt dann zu mir zurück.", sourceObjective = "Schließt 12 Runden im gemischten Einzel ab.", completion = "Euer Edelmut und Eure Stärke sind unbestreitbar. Nehmt das.", sourceObjectiveStatus = "unverified-source-field" }
quests[80186] = { id = 80186, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beständigkeit im Krieg", description = "Wenn Ihr an größeren Konflikten teilnehmt, verbessert sich Eure Fähigkeit, das große Ganze zu sehen. Geht und macht diese Erfahrungen. Kehrt hinterher zu mir zurück.", sourceObjective = "Verdient Ehre auf epischen Schlachtfeldern.", completion = "Ich wusste, dass Ihr es schaffen würdet. Hier, nehmt das.", sourceObjectiveStatus = "unverified-source-field" }
quests[80187] = { id = 80187, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beständigkeit in Scharmützeln", description = "Wiederholung ist Teil des Trainings. Mir ist zu Ohren gekommen, dass es da draußen andere wie Euch gibt, die an kleineren Scharmützeln teilnehmen. Geht und findet Trainingspartner zum Üben und kehrt anschließend zu mir zurück.\n\nZeigt, was Ihr zu zeigen habt, und kehrt dann zu mir zurück.", sourceObjective = "Verdient Ehre in Arenageplänkeln.", completion = "Exzellente Übung! Hier habt Ihr eine Kleinigkeit als Entschädigung.", sourceObjectiveStatus = "unverified-source-field" }
quests[80188] = { id = 80188, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beständigkeit in Arenen", description = "Schnelle und koordinierte Kämpfe sind selbst für die stärksten Kämpfer gewaltige Prüfungen. Findet Mitstreiter, die in der Arena an Eurer Seite gegen würdige Gegner kämpfen.", sourceObjective = "Verdient als Gruppe Ehre in gewerteten Arenen.", completion = "Überaus beeindruckend... nehmt das als Belohnung.", sourceObjectiveStatus = "unverified-source-field" }
quests[80189] = { id = 80189, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beständigkeit im Team", description = "Die Fähigkeit, zusammen mit anderen zu taktieren, um Ziele einzunehmen, ist der Schlüssel auf dem Weg, ein mächtiger Krieger zu werden. Begebt Euch aufs Schlachtfeld und kehrt anschließend zu mir zurück.", sourceObjective = "Verdient Ehre auf gewerteten Blitzschlachtfeldern oder gewerteten Schlachtfeldern.", completion = "Tolle Arbeit! Das habt Ihr Euch verdient.", sourceObjectiveStatus = "unverified-source-field" }
quests[80196] = { id = 80196, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Edelsteine extrahieren", description = "Jeder Edelstein kann mit der Fähigkeit 'Edelstein extrahieren' aus Eurer Ausrüstung entfernt werden.\n\nDer Edelstein wird nicht zerstört.\n\nExtrahiert jetzt einen Edelstein.", sourceObjective = "Extrahiert den gesprungenen tödlichen Saphir aus Eurer Ausrüstung.", sourceObjectiveStatus = "unverified-source-field" }
quests[80197] = { id = 80197, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Edelsteine kombinieren", description = "Prismatische Edelsteine können zu mächtigeren Edelsteinen kombiniert werden.\n\nKombiniert drei gesprungene tödliche Saphire, um einen fehlerhaften tödlichen Saphir zu erschaffen, der zusätzlichen kritischen Trefferwert gewährt, wenn Ihr ihn sockelt.", sourceObjective = "Nutzt drei gesprungene tödliche Saphire, um sie zu einem fehlerhaften tödlichen Saphir zu kombinieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[80202] = { id = 80202, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heißer Pollen", description = "Wichtig sein, nicht zu viel nehmen. Schwarm gesund sein müssen, damit wiederkommen können.\n\nBienen Pollen essen, ja? Feuerbienen also Feuerpollen essen? Ja?\n\nFeuerpollen zu Bienen bringen. Stark werden. Biene fleißig.\n\nIhr Rand von Schwarm prüfen, weil Bienen noch nicht dahin gekommen. Wenn Feuer fangen, gute Biene erwischt.", sourceObjective = "Sammelt Pollen von pollenreichen Aschenblüten und bringt ihn zu Bienen in Eurer Nähe, bevor die Pollen erlöschen.", progress = "Ihr nur ein bisschen brennen. Ihr hart im Nehmen, wird schon.", completion = "Gut. Gesunder Schwarm macht glückliches Wachs.", sourceObjectiveStatus = "unverified-source-field" }
